// src/play/autoplay.js
//
// Turns the walkthrough into the commands a person would actually type.
//
// The walkthrough is written for people to read ("trade apple and banana to a
// hunched witch for potion"). The game only understands commands ("give apple
// to hunched witch"). This file is the translator, and nothing else: it does
// not play, and it changes nothing. Play.jsx does the playing, through the same
// submit function a typed command goes through.
//
// Each step becomes:
//   moves  — directions to walk first
//   tries  — alternative ways to type the action, best first. Each try is a
//            list of commands run in order; the next try is used only if the
//            game's state did not change.
//   kind   — "act" | "skip" (nothing to type) | "stuck" (cannot be typed)

import { buildWalkthrough } from "../engine/engine";

const ARTICLE = /^(?:an?|the|some|my)\s+/i;
const bare = (s) => String(s ?? "").trim().replace(ARTICLE, "").replace(/\s+/g, " ");
const norm = (s) => bare(s).toLowerCase();

// Verbs the game itself treats as working a fixture.
const WORK_VERBS = new Set(["pull", "push", "turn", "twist", "wind", "crank", "flip", "lift", "lower",
  "press", "operate", "work", "search", "examine", "inspect"]);
const NOT_PROP_VERBS = new Set(["take", "obtain", "get", "drop", "give", "trade", "combine", "enter"]);

function buildIndex(world) {
  const out = { items: [], mobs: [], props: [] };
  for (const [id, it] of Object.entries(world.items ?? {})) {
    const typed = bare(it.short ?? it.name ?? id);
    for (const n of new Set([norm(it.short), norm(it.name)].filter(Boolean))) out.items.push({ id, name: n, typed });
  }
  for (const [id, m] of Object.entries(world.mobs ?? {})) {
    const typed = bare(m.name ?? id);
    if (m.name) out.mobs.push({ id, name: norm(m.name), typed });
  }
  for (const [id, p] of Object.entries(world.props ?? {})) {
    const typed = bare(p.name ?? id);
    if (p.name) out.props.push({ id, name: norm(p.name), typed });
  }
  return out;
}

/** Every known name found in the text, longest names first so "plate of
    cheese" wins over "cheese", in the order they appear. */
function locate(text, list) {
  const taken = [];
  const found = [];
  const sorted = [...list].sort((a, b) => b.name.length - a.name.length);
  for (const e of sorted) {
    let from = 0;
    for (;;) {
      const at = text.indexOf(e.name, from);
      if (at === -1) break;
      const end = at + e.name.length;
      const before = at === 0 ? " " : text[at - 1];
      const after = end >= text.length ? " " : text[end];
      from = at + 1;
      if (/[a-z0-9]/.test(before) || /[a-z0-9]/.test(after)) continue;
      if (taken.some(([s, t]) => at < t && end > s)) continue;
      taken.push([at, end]);
      found.push({ ...e, pos: at });
    }
  }
  return found.sort((a, b) => a.pos - b.pos);
}

const uniqTries = (tries) => {
  const seen = new Set();
  return tries.filter((t) => {
    const k = t.join("\n");
    if (!t.length || seen.has(k)) return false;
    seen.add(k);
    return true;
  });
};

/** One step's action → { kind, tries } or { kind: "stuck", reason }. */
function translate(action, idx) {
  const a = String(action ?? "").toLowerCase().trim();
  if (!a) return { kind: "stuck", reason: "This step has nothing to type." };
  const verb = a.split(/\s+/)[0];

  const items = locate(a, idx.items);
  const mobs = locate(a, idx.mobs);
  const props = locate(a, idx.props);

  // "unlock door with the key" is just walking through the door. But "unlock the
  // cellar door with the key" can be a fixture of its own that has to be worked.
  // "Reach the back hallway" is a quest stage that is only about being somewhere:
  // walking there (the step's moves) is the whole of it, nothing is typed.
  if (/^(enter|reach|go to|get to|arrive)\b/.test(a) || (/^unlock\b/.test(a) && !props.length)) return { kind: "skip" };

  if (/^(take|obtain|get|pick up)\b/.test(a)) {
    return items.length ? { kind: "act", tries: [[`take ${items[0].typed}`]] }
      : { kind: "stuck", reason: `I cannot tell what to take in "${action}".` };
  }
  if (/^drop\b/.test(a)) {
    return items.length ? { kind: "act", tries: [[`drop ${items[0].typed}`]] }
      : { kind: "stuck", reason: `I cannot tell what to drop in "${action}".` };
  }
  if (/^give\b/.test(a)) {
    return items.length && mobs.length
      ? { kind: "act", tries: [[`give ${items[0].typed} to ${mobs[0].typed}`]] }
      : { kind: "stuck", reason: `I cannot tell who gets what in "${action}".` };
  }
  if (/^trade\b/.test(a)) {
    const cut = a.indexOf(" to ");
    const wants = items.filter((i) => cut === -1 || i.pos < cut);
    const mob = mobs.find((m) => cut === -1 || m.pos > cut) ?? mobs[0];
    return wants.length && mob
      ? { kind: "act", tries: [wants.map((i) => `give ${i.typed} to ${mob.typed}`)] }
      : { kind: "stuck", reason: `I cannot tell what to hand over in "${action}".` };
  }
  if (/^combine\b/.test(a)) {
    const cut = a.indexOf(" into ");
    const parts = items.filter((i) => cut === -1 || i.pos < cut);
    return parts.length >= 2
      ? { kind: "act", tries: [[`combine ${parts.map((i) => i.typed).join(" and ")}`]] }
      : { kind: "stuck", reason: `I cannot tell what to combine in "${action}".` };
  }
  if (/^use\b.*\bon (?:self|myself|me)$/.test(a) && items.length) {
    return { kind: "act", tries: [[`use ${items[0].typed} on self`]] };
  }

  // A fixture: a lever, a valve, a socket, a note. Worked by its own verb or "use".
  if (props.length && !NOT_PROP_VERBS.has(verb)) {
    const p = props[0].typed;
    const lead = /^look at\b/.test(a) ? "look at" : WORK_VERBS.has(verb) ? verb : "use";
    const tries = [[`${lead} ${p}`], [`use ${p}`]];
    const needed = items.filter((i) => i.pos > props[0].pos);
    if (needed.length) tries.push(needed.map((i) => `use ${i.typed}`));
    if (needed.length === 1) tries.push([`use ${needed[0].typed} on ${p}`]);
    return { kind: "act", tries: uniqTries(tries) };
  }

  if (/^use\b/.test(a)) {
    if (items.length >= 2) return { kind: "act", tries: [[`use ${items[0].typed} on ${items[1].typed}`]] };
    if (items.length && mobs.length) return { kind: "act", tries: [[`give ${items[0].typed} to ${mobs[0].typed}`]] };
    if (items.length) return { kind: "act", tries: [[`use ${items[0].typed}`]] };
  }
  if (/^(eat|drink)\b/.test(a) && items.length) {
    return { kind: "act", tries: [[`${verb} ${items[0].typed}`]] };
  }

  return { kind: "stuck", reason: `I do not know how to type "${action}".` };
}

/** → { steps: [{ n, goal, text, moves, tries, kind, reason }] } or { error } */
export function planAutoplay(world) {
  let walk;
  try {
    walk = buildWalkthrough(JSON.parse(JSON.stringify(world)));
  } catch (e) {
    return { error: `The walkthrough could not be built: ${e?.message ?? e}` };
  }
  const idx = buildIndex(world);
  const steps = [];
  walk.forEach((s, i) => {
    const base = { n: i + 1, goal: s.goal ?? "", text: s.action ?? "", moves: [...(s.path ?? [])] };
    if (s.already) { steps.push({ ...base, kind: "skip" }); return; }
    if (s.note) { steps.push({ ...base, kind: "stuck", reason: s.note }); return; }
    // "unlock door with X" standing at a door: the player opens that door, which is
    // what keeps it open after the key is handed on. (Walking through a door opens
    // it on the way, so a step that only walks needs no typing.) "soft": if the door
    // turns out to be open already, nothing happens and that is fine.
    if (/^unlock\b/i.test(String(s.action ?? "")) && s.room) {
      const lowered = String(s.action).toLowerCase();
      const keys = locate(lowered, idx.props).length ? [] : locate(lowered, idx.items).map((i) => i.id);
      const dirs = Object.entries(world.rooms?.[s.room]?.exits ?? {})
        .filter(([, ex]) => ex && typeof ex === "object" && keys.includes(ex.locked)).map(([d]) => d);
      if (dirs.length) { steps.push({ ...base, kind: "act", soft: true, tries: [[`open ${dirs[0]}`]] }); return; }
    }
    const t = translate(s.action, idx);
    steps.push({ ...base, ...t });
  });
  return { steps };
}
