import React, { useEffect, useState } from "react";
import { GameCard } from "./Browse";
import { grid } from "../theme";
import { Btn, Empty, H1 } from "../ui/primitives";
import { loadCreationAccessMode } from "../lib/db";

export function Mine({ games, me, go }) {
  const [canCreate, setCanCreate] = useState(true); // optimistic default so the button doesn't flash away then back
  useEffect(() => {
    loadCreationAccessMode().then((mode) => setCanCreate(mode === "everyone" || Boolean(me?.isCreator))).catch(() => {});
  }, [me?.isCreator]);

  return (
    <div className="pf-in">
      <div style={{ display: "flex", alignItems: "flex-end", gap: 16, marginBottom: 22, flexWrap: "wrap" }}>
        <div style={{ flex: 1, minWidth: 220 }}><H1 sub="Drafts stay private until you publish them.">Your games</H1></div>
        {canCreate && <Btn kind="solid" onClick={() => go("create")}>Create a game</Btn>}
      </div>
      {games.length ? (
        <div style={grid}>{games.map((g) => (
          <GameCard key={g.id} g={g} go={go} showStatus
            onClick={() => go("game", { id: g.id, authorUsername: g.authorUsername, slug: g.slug, from: "mine" })} />
        ))}</div>
      ) : (
        <Empty title="You haven't built anything yet."
          line="A world takes one paragraph to describe and about a minute to generate."
          action={canCreate ? <Btn kind="solid" onClick={() => go("create")}>Create a game</Btn> : undefined} />
      )}
    </div>
  );
}
