export function AdminPage({ me, go }) {
  // Restored from localStorage so returning to this page lands back
  // where the admin left off, rather than always resetting to Settings.
  // Manage/Announcements is the fallback only when nothing's been saved
  // yet at all.
  const [mainTab, setMainTabState] = useState(() => {
    try { return localStorage.getItem("admin_main_tab") || "manage"; } catch { return "manage"; }
  });
  const [tab, setTabState] = useState(() => {
    try { return localStorage.getItem("admin_sub_tab") || "announcements"; } catch { return "announcements"; }
  });

  if (!me.isAdmin) {
    return <Empty title="Not for you." line="This page is for platform administrators." />;
  }

  const setTab = (t) => {
    setTabState(t);
    try { localStorage.setItem("admin_sub_tab", t); } catch {}
  };
  const selectMain = (g) => {
    setMainTabState(g);
    try { localStorage.setItem("admin_main_tab", g); } catch {}
    setTab(TAB_GROUPS[g][0][0]);
  };

  return (
    <div className="pf-in" style={{ maxWidth: 620 }}>
      <Btn kind="ghost" onClick={() => go("browse")} style={{ marginBottom: 16 }}>back</Btn>

      <H1 sub="Platform settings. These apply to every creator, so a bad choice here is felt by everyone.">
        Admin
      </H1>

      <div style={{ display: "flex", gap: 4, borderBottom: "1px solid " + T.edge, marginBottom: 4 }}>
        {MAIN_TABS.map(([k, label]) => (
          <button key={k} onClick={() => selectMain(k)} className="pf-btn"
            style={{ background: "none", border: "none", cursor: "pointer", padding: "10px 16px",
              fontFamily: T.serif, fontSize: 15, color: mainTab === k ? T.bone : T.boneDim,
              boxShadow: mainTab === k ? "inset 0 -2px 0 " + T.ochre : "none" }}>
            {label}
          </button>
        ))}
      </div>

      <div className="pf-scroll-x"
        onWheel={(e) => {
          // A plain mouse wheel only ever produces vertical delta — this
          // redirects that into horizontal movement so hovering the row
          // and scrolling normally moves it left/right, rather than
          // requiring a trackpad's native horizontal gesture or Shift+scroll.
          if (e.deltaY === 0) return;
          e.currentTarget.scrollLeft += e.deltaY;
          e.preventDefault();
        }}
        style={{ display: "flex", gap: 4, marginBottom: 24, overflowX: "auto", whiteSpace: "nowrap" }}>
        {TAB_GROUPS[mainTab].map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)} className="pf-btn"
            style={{ background: tab === k ? T.ochre : "transparent",
              color: tab === k ? "#221D0C" : T.boneDim,
              border: "1px solid " + (tab === k ? T.ochre : T.edge),
              borderRadius: 2, cursor: "pointer", padding: "7px 13px", flexShrink: 0,
              fontFamily: T.mono, fontSize: 12 }}>
            {label}
          </button>
        ))}
      </div>

      {tab === "narrator" && <NarratorTab />}
      {tab === "world_building" && <WorldBuildingTab />}
      {tab === "image_generation" && <ImageGenerationTab />}
      {tab === "themes" && <ThemesTab />}
      {tab === "story_crawl" && <StoryCrawlTab />}
      {tab === "access_stage" && <AccessStageTab />}

      {tab === "balance" && <ProviderBalances />}
      {tab === "database" && <StorageBucketsTab />}
      {tab === "activity_log" && <ActivityLogTab />}
      {tab === "finance" && <FinanceTab />}

      {tab === "usernames" && <UsernamesTab />}
      {tab === "users" && <UsersTab />}
      {tab === "announcements" && <AnnouncementsTab />}
      {tab === "reports" && <ReportQueue me={me} />}
      {tab === "invite_codes" && <InviteCodesTab />}

      {tab === "trailers" && <TrailersTab />}
      {tab === "waitlist" && <WaitlistTab />}
    </div>
  );
}

function NarratorTab() {
  const [setting, setSetting] = useState(null);
  const [error, setError] = useState(null);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    loadSetting("generator")
      .then((v) => setSetting({ provider: v.provider ?? "deepseek", model: v.model ?? "" }))
      .catch((e) => setError(e.message));
  }, []);

  const write = async (next) => {
    setSetting(next);
    setError(null);
    try {
      await saveSetting("generator", next);
      setSaved(true);
      setTimeout(() => setSaved(false), 1600);
    } catch (e) {
      setError(e.message);
    }
  };

  if (!setting) return <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>;

  return (
    <>
      <Field
        label="World generator"
        hint="Which model turns a creator's brief into a world. The prompt is identical for all three; only the model changes.">
        <div style={{ display: "grid", gap: 8 }}>
          {PROVIDERS.map((p) => {
            const on = setting.provider === p.key;
            return (
              <button key={p.key} className="pf-btn"
                onClick={() => write({ ...setting, provider: p.key })}
                style={{ textAlign: "left", padding: "12px 14px", borderRadius: 2, cursor: "pointer",
                  background: "transparent",
                  border: "1px solid " + (on ? T.ochre : T.edge) }}>
                <div style={{ fontFamily: T.serif, fontSize: 17,
                  color: on ? T.bone : T.boneDim, marginBottom: 4 }}>
                  {p.label}{p.key === "deepseek" ? " — default" : ""}
                </div>
                <div style={{ fontFamily: T.mono, fontSize: 11.5, lineHeight: 1.6, color: T.boneDim }}>
                  {p.note}
                </div>
              </button>
            );
          })}
        </div>
      </Field>

      <Field
        label="Model override"
        hint="Leave empty to use the default for the chosen provider. Set it to pin a specific version, or to try a newer one without a redeploy.">
        <input
          value={setting.model}
          onChange={(e) => setSetting({ ...setting, model: e.target.value })}
          onBlur={(e) => write({ ...setting, model: e.target.value.trim() })}
          placeholder="e.g. claude-sonnet-5"
          style={{ ...inputStyle, fontFamily: T.mono, fontSize: 13 }} />
      </Field>

      <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, lineHeight: 1.7 }}>
        {saved ? "saved" : "\u00a0"}
      </p>

      <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 18, marginTop: 8 }}>
        <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: 0 }}>
          Each provider needs its key set on the project: DEEPSEEK_API_KEY, ANTHROPIC_API_KEY
          or OPENAI_API_KEY. Choosing one without its key fails the next generation with a
          message saying which is missing. The result of every build names the model that made
          it, so the same brief can be run through two and compared.
        </p>
      </div>

      {error && (
        <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7,
          border: "1px solid " + T.clay + "44", padding: 12, borderRadius: 2, marginTop: 18 }}>
          {error}
        </p>
      )}
    </>
  );
}

