// Supabase free tier limits
const SUPABASE_FREE_STORAGE_BYTES = 1 * 1024 * 1024 * 1024;      // 1 GB
const SUPABASE_FREE_DB_BYTES      = 500 * 1024 * 1024;             // 500 MB
const SUPABASE_FREE_BANDWIDTH     = 5  * 1024 * 1024 * 1024;       // 5 GB/month
const SUPABASE_FREE_EDGE_CALLS    = 500_000;                        // 500K/month

function fmtBytes(bytes) {
  if (bytes === 0) return "0 B";
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
  if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(2) + " MB";
  return (bytes / (1024 * 1024 * 1024)).toFixed(3) + " GB";
}

/** A single limit row: label, used value (or null = unknown), limit string, optional bar. */
function LimitRow({ label, used, limitLabel, limitBytes, note }) {
  const pct = (limitBytes && used != null) ? Math.min(100, (used / limitBytes) * 100) : null;
  const barColor = pct == null ? T.edge : pct > 85 ? T.clay : pct > 60 ? T.ochre : "#6aa86a";
  return (
    <div style={{ padding: "12px 0", borderBottom: "1px solid " + T.edge }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: pct != null ? 5 : 0 }}>
        <span style={{ fontFamily: T.mono, fontSize: 12, color: T.bone }}>{label}</span>
        <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, textAlign: "right" }}>
          {used != null
            ? <><span style={{ color: T.bone }}>{limitBytes ? fmtBytes(used) : used.toLocaleString()}</span>{" / "}</>
            : null}
          {limitLabel}
        </span>
      </div>
      {pct != null && (
        <div style={{ height: 3, background: T.edge, borderRadius: 2, overflow: "hidden" }}>
          <div style={{ height: "100%", width: pct + "%", background: barColor, borderRadius: 2, transition: "width 0.4s" }} />
        </div>
      )}
      {note && <p style={{ fontFamily: T.mono, fontSize: 10, color: T.boneDim, margin: "4px 0 0", lineHeight: 1.5 }}>{note}</p>}
    </div>
  );
}

function StorageBucketsTab() {
  const [buckets, setBuckets] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const load = async () => {
    setLoading(true); setError(null);
    try {
      const result = await loadStorageStats();
      setBuckets(result.buckets ?? []);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const totalStorageUsed = buckets ? buckets.reduce((sum, b) => sum + (b.bytes ?? 0), 0) : null;
  const storagePct = totalStorageUsed != null ? Math.min(100, (totalStorageUsed / SUPABASE_FREE_STORAGE_BYTES) * 100) : null;
  const storageBarColor = storagePct == null ? T.edge : storagePct > 85 ? T.clay : storagePct > 60 ? T.ochre : "#6aa86a";

  return (
    <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 18, marginTop: 18 }}>
      {/* ── Header ── */}
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 4 }}>
        <h3 style={{ fontFamily: T.serif, fontSize: 17, color: T.bone, margin: 0 }}>Supabase free tier</h3>
        <button onClick={load} className="pf-btn" disabled={loading}
          style={{ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11,
            color: T.boneDim, cursor: loading ? "default" : "pointer" }}>
          {loading ? "refreshing…" : "refresh"}
        </button>
      </div>
      <p style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, margin: "0 0 14px", lineHeight: 1.5 }}>
        Live values from Supabase dashboard → Settings → Usage. Storage bucket sizes are live via the API.
      </p>

      {error && (
        <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.6, marginBottom: 12 }}>
          {error}
        </p>
      )}

      {/* ── Free tier limits — Supabase doesn't expose these via API ── */}
      <div style={{ marginBottom: 16 }}>
        {[
          ["Database size", "500 MB"],
          ["Auth users", "Unlimited"],
          ["Edge Function invocations", "500K / month"],
          ["Bandwidth", "5 GB / month (egress)"],
        ].map(([label, limit]) => (
          <div key={label} style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline",
            padding: "10px 0", borderBottom: "1px solid " + T.edge }}>
            <span style={{ fontFamily: T.mono, fontSize: 12, color: T.bone }}>{label}</span>
            <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>{limit}</span>
          </div>
        ))}
        <p style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, margin: "8px 0 0", lineHeight: 1.5 }}>
          Current usage for these is only available in the{" "}
          <a href="https://supabase.com/dashboard/org/mwhqrcvgdcznjckdjolw/usage?projectRef=ddyzkwwkfcnvisgklkhl" target="_blank" rel="noopener noreferrer"
            style={{ color: T.ochre }}>Supabase dashboard → Usage</a>.
        </p>
      </div>

      {/* ── Storage buckets (live) ── */}
      <div style={{ marginTop: 20, marginBottom: 10 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 6 }}>
          <span style={{ fontFamily: T.serif, fontSize: 15, color: T.bone }}>Storage buckets</span>
          {totalStorageUsed != null && (
            <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
              <span style={{ color: T.bone }}>{fmtBytes(totalStorageUsed)}</span>
              {" / 1 GB "}
              <span style={{ color: storagePct > 85 ? T.clay : storagePct > 60 ? T.ochre : "#6aa86a" }}>
                {storagePct.toFixed(1)}%
              </span>
            </span>
          )}
        </div>
        {totalStorageUsed != null && (
          <div style={{ height: 4, background: T.edge, borderRadius: 2, overflow: "hidden", marginBottom: 14 }}>
            <div style={{ height: "100%", width: storagePct + "%", background: storageBarColor, borderRadius: 2, transition: "width 0.4s" }} />
          </div>
        )}
      </div>

      {buckets && buckets.length === 0 && (
        <p style={{ fontFamily: T.serif, fontSize: 14, color: T.boneDim, fontStyle: "italic" }}>No buckets found.</p>
      )}
      {buckets && buckets.map((b) => {
        const sz = b.bytes ?? 0;
        const bucketPct = totalStorageUsed > 0 ? (sz / totalStorageUsed) * 100 : 0;
        return (
          <div key={b.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline",
            padding: "10px 0", borderBottom: "1px solid " + T.edge }}>
            <div>
              <span style={{ fontFamily: T.serif, fontSize: 15, color: T.bone }}>{b.name}</span>
              <span style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, marginLeft: 8 }}>
                {b.public ? "public" : "private"}
              </span>
            </div>
            <span style={{ fontFamily: T.mono, fontSize: 12, color: T.bone, textAlign: "right" }}>
              {fmtBytes(sz)}
              {totalStorageUsed > 0 && (
                <span style={{ color: T.boneDim, marginLeft: 6 }}>({bucketPct.toFixed(1)}%)</span>
              )}
            </span>
          </div>
        );
      })}

      {!buckets && !error && (
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading…</p>
      )}
    </div>
  );
}

