function AnnouncementsTab() {
  const [items, setItems] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);

  const [text, setText] = useState("");
  const [url, setUrl] = useState("");
  const [visibility, setVisibility] = useState("everyone");
  const [startsAt, setStartsAt] = useState("");
  const [endsAt, setEndsAt] = useState("");

  const refresh = () => {
    loadAllAnnouncements().then(setItems).catch((e) => setError(e.message));
  };
  useEffect(() => { refresh(); }, []);

  const add = async () => {
    if (!text.trim()) return;
    setBusy(true); setError(null);
    try {
      await addAnnouncement({
        text: text.trim(), imagePath: "", url: url.trim(), visibility,
        startsAt: startsAt || null, endsAt: endsAt || null,
      });
      setText(""); setUrl("");
      setStartsAt(""); setEndsAt("");
      refresh();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const toggle = async (id, active) => {
    setBusy(true); setError(null);
    try {
      await setAnnouncementActive(id, active);
      refresh();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const remove = async (id) => {
    setBusy(true); setError(null);
    try {
      await removeAnnouncement(id);
      refresh();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim, lineHeight: 1.6, marginBottom: 20 }}>
        Shown as a dismissible banner across the app. Checking one announcement shows it; checking
        several means one is picked at random among them each time. An optional date window
        restricts a checked announcement to that range — leave both blank to run for as long as it
        stays checked.
      </p>

      <div style={{ border: "1px solid " + T.edge, borderRadius: 2, padding: 16, marginBottom: 24 }}>
        <div style={{ fontFamily: T.serif, fontSize: 16, marginBottom: 12 }}>New announcement</div>
        <textarea rows="2" placeholder="Support our Kickstarter campaign\u2026"
          style={{ ...inputStyle, width: "100%", marginBottom: 12, resize: "vertical" }}
          value={text} onChange={(e) => setText(e.target.value)} />

        <input placeholder="Link when clicked (optional)" style={{ ...inputStyle, width: "100%", marginBottom: 10 }}
          value={url} onChange={(e) => setUrl(e.target.value)} />

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8, marginBottom: 10 }}>
          <select style={inputStyle} value={visibility} onChange={(e) => setVisibility(e.target.value)}>
            <option value="everyone">Everyone</option>
            <option value="logged_in">Logged-in only</option>
            <option value="signed_out">Signed-out only</option>
          </select>
          <input type="date" style={inputStyle} value={startsAt} onChange={(e) => setStartsAt(e.target.value)}
            title="Starts (optional)" />
          <input type="date" style={inputStyle} value={endsAt} onChange={(e) => setEndsAt(e.target.value)}
            title="Ends (optional)" />
        </div>
        <Btn kind="solid" disabled={busy || !text.trim()} onClick={add}>Add announcement</Btn>
      </div>

      {error && <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, marginBottom: 14 }}>{error}</p>}

      {items === null ? (
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
      ) : items.length === 0 ? (
        <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>Nothing yet.</p>
      ) : (
        <div style={{ display: "grid", gap: 8 }}>
          {items.map((a) => (
            <div key={a.id} style={{ display: "flex", gap: 12, alignItems: "flex-start",
              border: "1px solid " + T.edge, borderRadius: 2, padding: 12 }}>
              <input type="checkbox" checked={a.active} disabled={busy}
                onChange={(e) => toggle(a.id, e.target.checked)}
                style={{ marginTop: 3, cursor: "pointer" }} />
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: T.serif, fontSize: 14, marginBottom: 3 }}>{a.text}</div>
                <div style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim }}>
                  {a.visibility === "everyone" ? "everyone" : a.visibility === "logged_in" ? "logged-in only" : "signed-out only"}
                  {(a.startsAt || a.endsAt) && ` \u00b7 ${a.startsAt ?? "\u2026"} \u2192 ${a.endsAt ?? "\u2026"}`}
                  {a.imageUrl && " \u00b7 has image"}
                  {a.url && " \u00b7 links out"}
                </div>
              </div>
              <button onClick={() => remove(a.id)} disabled={busy} className="pf-btn"
                style={{ background: "none", border: "none", padding: 0, cursor: "pointer", color: T.clay, fontSize: 13 }}>
                {"\u00d7"}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function FinanceTab() {
  const [expenses, setExpenses] = useState(null);
  const [finance, setFinance] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);

  const [description, setDescription] = useState("");
  const [category, setCategory] = useState(EXPENSE_CATEGORIES[0]);
  const [amount, setAmount] = useState("");
  const [incurredOn, setIncurredOn] = useState(() => new Date().toISOString().slice(0, 10));
  const [notes, setNotes] = useState("");
  const [recurring, setRecurring] = useState(false);
  const [frequency, setFrequency] = useState("monthly");

  const [purchasesEnabled, setPurchasesEnabled] = useState(null);

  const refresh = () => {
    loadExpenses().then(setExpenses).catch((e) => setError(e.message));
    loadFinanceSummary().then(setFinance).catch((e) => setError(e.message));
    loadSetting("purchases_enabled").then((v) => setPurchasesEnabled(v?.enabled !== false)).catch(() => setPurchasesEnabled(true));
  };
  useEffect(() => { refresh(); }, []);

  const togglePurchases = async () => {
    const next = !purchasesEnabled;
    setPurchasesEnabled(next); // optimistic
    try {
      await saveSetting("purchases_enabled", { enabled: next });
    } catch (e) {
      setPurchasesEnabled(!next);
      setError(e.message);
    }
  };

  const total = (expenses ?? []).reduce((sum, e) => sum + e.amountCents, 0);

  const add = async () => {
    const cents = Math.round(Number(amount) * 100);
    if (!description.trim() || !cents || cents <= 0) return;
    setBusy(true); setError(null);
    try {
      await addExpense({
        description: description.trim(), category, amountCents: cents, incurredOn,
        notes: notes.trim(), recurring, frequency,
      });
      setDescription(""); setAmount(""); setNotes(""); setRecurring(false);
      refresh();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const remove = async (id) => {
    setBusy(true); setError(null);
    try {
      await removeExpense(id);
      refresh();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      {purchasesEnabled !== null && (
        <div style={{ border: "1px solid " + (purchasesEnabled ? T.edge : T.clay), borderRadius: 2,
          padding: 12, marginBottom: 20, display: "flex", alignItems: "center", gap: 14 }}>
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: T.serif, fontSize: 14, marginBottom: 2 }}>
              Credit purchases {purchasesEnabled ? "are open" : "are turned off"}
            </div>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
              Turning this off stops new checkouts platform-wide, before public launch or during
              maintenance. Existing balances aren't affected.
            </div>
          </div>
          <Btn kind={purchasesEnabled ? "ghost" : "solid"} onClick={togglePurchases}>
            {purchasesEnabled ? "Turn off" : "Turn on"}
          </Btn>
        </div>
      )}

      <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim, lineHeight: 1.6, marginBottom: 20 }}>
        Revenue below is pulled directly from the purchases table Stripe payments actually write to.
        Expenses are a plain ledger — right now every entry is added by hand; automated sources
        (Stripe's own processing fee, provider spend) will feed into this same list later rather
        than a separate one.
      </p>

      {finance && (
        <div style={{ marginBottom: 28 }}>
          <div style={{ fontFamily: T.serif, fontSize: 16, marginBottom: 10 }}>Last 30 days</div>
          <div style={{ border: "1px solid " + T.edge, borderRadius: 2, padding: 4, marginBottom: 14 }}>
            {[
              ["Revenue", finance.revenueCents, T.bone, false],
              ["Stripe's fee", -finance.stripeFeesCents, T.clay, true],
              ["Image generation (est.)", -finance.imageGenCostCents, T.clay, true],
              ["Recurring expenses", -finance.recurringMonthlyCents, T.clay, true],
              ["One-off expenses", -finance.oneOffExpensesCents, T.clay, true],
            ].map(([label, cents, color, indent]) => (
              <div key={label} style={{ display: "flex", justifyContent: "space-between",
                padding: "7px 12px", fontFamily: T.mono, fontSize: 12.5, color: T.boneDim }}>
                <div style={{ paddingLeft: indent ? 14 : 0 }}>{label}</div>
                <div style={{ color }}>{cents < 0 ? "\u2212" : ""}{money(Math.abs(cents))}</div>
              </div>
            ))}
            <div style={{ display: "flex", justifyContent: "space-between", padding: "10px 12px",
              borderTop: "1px solid " + T.edge, fontFamily: T.serif, fontSize: 16 }}>
              <div>Net profit</div>
              <div style={{ color: finance.netProfitCents >= 0 ? T.moss : T.clay }}>{money(finance.netProfitCents)}</div>
            </div>
          </div>
          <p style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, lineHeight: 1.6, margin: 0 }}>
            Stripe's fee is computed per purchase (2.9% + $0.30), not a flat percentage of the total.
            Image generation is estimated — credit_events doesn't record which engine was used for
            every kind, so this applies a single ratio (currently defaulting to 46%, roughly the
            blended real cost of flux and pixel generation) to everything actually charged for a
            picture. Recurring expenses below are converted to their monthly equivalent automatically.
          </p>
        </div>
      )}

      <div style={{ border: "1px solid " + T.edge, borderRadius: 2, padding: 16, marginBottom: 24 }}>
        <div style={{ fontFamily: T.serif, fontSize: 16, marginBottom: 12 }}>Add an expense</div>
        <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 8, marginBottom: 8 }}>
          <input placeholder="Description" style={inputStyle} value={description}
            onChange={(e) => setDescription(e.target.value)} />
          <select style={inputStyle} value={category} onChange={(e) => setCategory(e.target.value)}>
            {EXPENSE_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 8 }}>
          <input type="number" step="0.01" min="0" placeholder="Amount ($)" style={inputStyle}
            value={amount} onChange={(e) => setAmount(e.target.value)} />
          <input type="date" style={inputStyle} value={incurredOn}
            onChange={(e) => setIncurredOn(e.target.value)} />
        </div>
        <label style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8,
          fontFamily: T.mono, fontSize: 12, color: T.boneDim, cursor: "pointer" }}>
          <input type="checkbox" checked={recurring} onChange={(e) => setRecurring(e.target.checked)} />
          Recurring
          {recurring && (
            <select style={{ ...inputStyle, marginLeft: 4 }} value={frequency}
              onChange={(e) => setFrequency(e.target.value)}>
              <option value="monthly">monthly</option>
              <option value="yearly">yearly</option>
            </select>
          )}
        </label>
        <input placeholder="Notes (optional)" style={{ ...inputStyle, width: "100%", marginBottom: 10 }}
          value={notes} onChange={(e) => setNotes(e.target.value)} />
        <Btn kind="solid" disabled={busy || !description.trim() || !amount} onClick={add}>Add expense</Btn>
      </div>

      {error && <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, marginBottom: 14 }}>{error}</p>}

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 12 }}>
        <div style={{ fontFamily: T.serif, fontSize: 16 }}>Expenses</div>
        <div style={{ fontFamily: T.mono, fontSize: 13, color: T.bone }}>Total: {money(total)}</div>
      </div>

      {expenses === null ? (
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
      ) : (
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: T.mono, fontSize: 12 }}>
            <thead>
              <tr style={{ borderBottom: `1px solid ${T.edge}`, textAlign: "left", color: T.boneDim }}>
                <th style={{ padding: "6px 8px" }}>Date</th>
                <th style={{ padding: "6px 8px" }}>Description</th>
                <th style={{ padding: "6px 8px" }}>Category</th>
                <th style={{ padding: "6px 8px" }}>Source</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Amount</th>
                <th style={{ padding: "6px 8px" }}></th>
              </tr>
            </thead>
            <tbody>
              {expenses.map((e) => (
                <tr key={e.id} style={{ borderBottom: `1px solid ${T.edge}` }}>
                  <td style={{ padding: "6px 8px", color: T.boneDim, whiteSpace: "nowrap" }}>{e.incurredOn}</td>
                  <td style={{ padding: "6px 8px" }}>
                    {e.description}
                    {e.notes && <div style={{ color: T.boneDim, fontSize: 10.5 }}>{e.notes}</div>}
                  </td>
                  <td style={{ padding: "6px 8px", color: T.boneDim }}>
                    {e.category}{e.recurring && ` \u00b7 ${e.frequency}`}
                  </td>
                  <td style={{ padding: "6px 8px", color: T.boneDim }}>{e.source}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right" }}>{money(e.amountCents)}</td>
                  <td style={{ padding: "6px 8px" }}>
                    <button onClick={() => remove(e.id)} disabled={busy} className="pf-btn"
                      style={{ background: "none", border: "none", padding: 0, cursor: "pointer", color: T.clay, fontSize: 13 }}>
                      {"\u00d7"}
                    </button>
                  </td>
                </tr>
              ))}
              {expenses.length === 0 && (
                <tr><td colSpan={6} style={{ padding: "16px 8px", color: T.boneDim, textAlign: "center" }}>
                  No expenses logged yet.
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

