function PlayStats() {
  const [rows, setRows] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [query, setQuery] = useState("");
  const [filteredName, setFilteredName] = useState(null); // set once narrowed to one person

  const load = async (userId) => {
    setLoading(true); setError(null);
    try {
      setRows(await loadPlayStats({ userId, limit: 20 }));
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const search = async () => {
    const q = query.trim();
    if (!q) { setFilteredName(null); load(); return; }
    setLoading(true); setError(null);
    try {
      const found = await adminSearchUsers(q);
      if (found.length === 0) {
        setError("No matches.");
        setRows([]);
      } else if (found.length === 1) {
        setFilteredName(found[0].name || found[0].username);
        await load(found[0].id);
      } else {
        // More than one match — same convention as Detailed: fall back
        // to the top-20 view isn't right here, so just ask for a
        // narrower query rather than guessing which one was meant.
        setError(`${found.length} people match "${q}" — try a more specific search.`);
        setRows([]);
      }
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim, marginBottom: 12 }}>
        Hours played is a session-bucketed estimate — turns within 20 minutes of each other count
        as one session — not an exact stopwatch. Games played counts distinct worlds touched.
      </p>

      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        <input value={query} onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && search()}
          placeholder="Search by username, display name, or email \u2014 leave empty for the top 20"
          style={{ ...inputStyle, width: "auto", flex: 1, fontSize: 12.5 }} />
        <Btn kind="ghost" onClick={search}>{loading ? "Loading\u2026" : "Filter"}</Btn>
      </div>

      {filteredName && (
        <p style={{ fontFamily: T.serif, fontSize: 15, color: T.bone, marginBottom: 12 }}>{filteredName}</p>
      )}

      {error && <p style={{ color: T.clay, fontFamily: T.mono, fontSize: 12 }}>{error}</p>}

      {rows && (
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: T.mono, fontSize: 12 }}>
            <thead>
              <tr style={{ borderBottom: `1px solid ${T.edge}`, textAlign: "left", color: T.boneDim }}>
                <th style={{ padding: "6px 8px" }}>User</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }} colSpan={1}>Hours (day)</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Hours (week)</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Hours (month)</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Hours (year)</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Games (day)</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Games (week)</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Games (month)</th>
                <th style={{ padding: "6px 8px", textAlign: "right" }}>Games (year)</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.userId} style={{ borderBottom: `1px solid ${T.edge}` }}>
                  <td style={{ padding: "6px 8px" }}>{r.displayName || r.username}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right", color: T.boneDim }}>{r.hoursToday.toFixed(1)}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right", color: T.boneDim }}>{r.hoursWeek.toFixed(1)}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right", color: T.boneDim }}>{r.hoursMonth.toFixed(1)}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right" }}>{r.hoursYear.toFixed(1)}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right", color: T.boneDim }}>{r.gamesToday}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right", color: T.boneDim }}>{r.gamesWeek}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right", color: T.boneDim }}>{r.gamesMonth}</td>
                  <td style={{ padding: "6px 8px", textAlign: "right" }}>{r.gamesYear}</td>
                </tr>
              ))}
              {rows.length === 0 && !error && (
                <tr><td colSpan={9} style={{ padding: "16px 8px", color: T.boneDim, textAlign: "center" }}>
                  No play activity yet.
                </td></tr>
              )}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

