function DetailedActivity({ initialUser }) {
  // Same single-text-field search as the Users tab, reusing that exact
  // RPC rather than building a separate filter mechanism.
  const [query, setQuery] = useState("");
  const [results, setResults] = useState(null);
  const [searching, setSearching] = useState(false);
  const [selected, setSelected] = useState(initialUser); // { id, name, email }
  const [events, setEvents] = useState(null);
  const [error, setError] = useState(null);
  const [loadingEvents, setLoadingEvents] = useState(false);

  const loadFor = async (userId, name, email) => {
    setSelected({ id: userId, name, email });
    setResults(null);
    setLoadingEvents(true); setError(null);
    try {
      setEvents(await loadCreditEvents({ userId, limit: 200 }));
    } catch (e) {
      setError(e.message);
    } finally {
      setLoadingEvents(false);
    }
  };

  const search = async () => {
    setSearching(true); setError(null);
    setSelected(null); setEvents(null);
    try {
      const found = await adminSearchUsers(query.trim());
      if (found.length === 1) {
        // Exactly one match — go straight to their details rather than
        // making the admin click a button to open the only possible
        // result.
        await loadFor(found[0].id, found[0].name || found[0].username, found[0].email);
      } else {
        setResults(found);
      }
    } catch (e) {
      setError(e.message);
    } finally {
      setSearching(false);
    }
  };

  useEffect(() => {
    if (initialUser?.id) loadFor(initialUser.id, initialUser.name, initialUser.email);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialUser?.id]);

  return (
    <div>
      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        <input value={query} onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && search()}
          placeholder="Search by username, display name, or email"
          style={{ ...inputStyle, width: "auto", flex: 1, fontSize: 12.5 }} />
        <Btn kind="ghost" onClick={search}>{searching ? "Searching\u2026" : "Search"}</Btn>
      </div>

      {error && <p style={{ color: T.clay, fontFamily: T.mono, fontSize: 12 }}>{error}</p>}

      {results && (
        <div style={{ display: "flex", flexDirection: "column", gap: 4, marginBottom: 16 }}>
          {results.map((u) => (
            <button key={u.id} onClick={() => loadFor(u.id, u.name || u.username, u.email)} className="pf-btn"
              style={{ textAlign: "left", background: "none", border: "1px solid " + T.edge, borderRadius: 2,
                cursor: "pointer", padding: "8px 12px", fontFamily: T.mono, fontSize: 12.5, color: T.bone }}>
              {u.name || u.username} <span style={{ color: T.boneDim }}>{u.email ? `\u00b7 ${u.email}` : ""}</span>
            </button>
          ))}
          {results.length === 0 && (
            <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>No matches.</p>
          )}
        </div>
      )}

      {selected && (
        <div style={{ marginBottom: 12 }}>
          <span style={{ fontFamily: T.serif, fontSize: 16, color: T.bone }}>{selected.name}</span>
          {selected.email && (
            <span style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim, marginLeft: 8 }}>
              {"\u00b7"} {selected.email}
            </span>
          )}
        </div>
      )}

      {loadingEvents && (
        <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>Loading\u2026</p>
      )}
      {events && !loadingEvents && <EventsTable events={events} />}
    </div>
  );
}

