function InviteCodesTab() {
  const [label, setLabel] = useState("");
  const [count, setCount] = useState(10);
  const [generated, setGenerated] = useState(null); // array of code strings, or null before first generate
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [copied, setCopied] = useState(false);
  const [stats, setStats] = useState(null);

  const refreshStats = () => {
    loadInviteCodeStats().then(setStats).catch((e) => setError(e.message));
  };
  useEffect(refreshStats, []);

  const onGenerate = async () => {
    setBusy(true);
    setError(null);
    setCopied(false);
    try {
      const codes = await generateInviteCodes(label.trim(), Math.min(500, Math.max(1, Math.round(count))));
      setGenerated(codes);
      refreshStats();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const onCopy = async () => {
    try {
      await navigator.clipboard.writeText(generated.join("\n"));
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      setError("Could not copy — your browser may be blocking clipboard access. Select the text and copy it manually.");
    }
  };

  return (
    <div>
      <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim, lineHeight: 1.6, marginBottom: 20 }}>
        Signup requires a valid, unused code — this generates a batch of single-use codes tagged with a
        label (a creator's name, a platform, a campaign) so you can trace signups back to where they came
        from later.
      </p>

      <div style={{ display: "flex", gap: 10, alignItems: "end", flexWrap: "wrap", marginBottom: 14 }}>
        <Field label="Label (who these are for)">
          <input value={label} onChange={(e) => setLabel(e.target.value)} placeholder="e.g. some_creator_name"
            style={{ ...inputStyle, width: 220 }} />
        </Field>
        <Field label="How many codes">
          <input type="number" min="1" max="500" value={count}
            onChange={(e) => setCount(e.target.value)} style={{ ...inputStyle, width: 100 }} />
        </Field>
        <Btn kind="solid" onClick={onGenerate} disabled={busy}>
          {busy ? "Generating\u2026" : "Generate"}
        </Btn>
      </div>

      {generated && (
        <div style={{ marginBottom: 24 }}>
          <textarea readOnly value={generated.join("\n")} rows={Math.min(12, generated.length)}
            style={{ ...inputStyle, width: "100%", fontFamily: T.mono, fontSize: 12.5,
              resize: "vertical", marginBottom: 8 }} />
          <Btn kind="ghost" onClick={onCopy}>{copied ? "Copied" : "Copy to clipboard"}</Btn>
        </div>
      )}

      {error && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginBottom: 16 }}>{error}</p>}

      <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 10 }}>By label</div>
      {!stats ? (
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
      ) : !stats.length ? (
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>No codes generated yet.</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: T.mono, fontSize: 12 }}>
          <thead>
            <tr style={{ borderBottom: "1px solid " + T.edge, color: T.boneDim, textAlign: "left" }}>
              <th style={{ padding: "6px 8px" }}>Label</th>
              <th style={{ padding: "6px 8px" }}>Used</th>
              <th style={{ padding: "6px 8px" }}>Total</th>
            </tr>
          </thead>
          <tbody>
            {stats.map((s) => (
              <tr key={s.label} style={{ borderBottom: "1px solid " + T.edge }}>
                <td style={{ padding: "6px 8px" }}>{s.label}</td>
                <td style={{ padding: "6px 8px", color: T.moss }}>{s.used}</td>
                <td style={{ padding: "6px 8px" }}>{s.total}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export function ReportQueue({ me }) {
  const [rows, setRows] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(null);

  const refresh = () => loadReports().then(setRows).catch((e) => setError(e.message));
  useEffect(() => { refresh(); }, []);

  const act = async (row, unpublish) => {
    setBusy(row.id);
    try {
      if (unpublish) await unpublishWorld(row.world_id);
      await resolveReport(row.id);
      await refresh();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(null);
    }
  };

  if (!me.isAdmin) return null;

  return (
    <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 24, marginTop: 28 }}>
      <h2 style={{ fontFamily: T.serif, fontSize: 20, fontWeight: 400, margin: "0 0 4px" }}>Reports</h2>
      <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 18px" }}>
        Unpublishing hides a world without destroying the creator's work or anyone's playthrough,
        which makes it the right first move in nearly every case.
      </p>

      {error && (
        <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7 }}>{error}</p>
      )}

      {rows === null ? (
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
      ) : rows.length === 0 ? (
        <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>Nothing waiting.</p>
      ) : (
        rows.map((r) => (
          <div key={r.id} style={{ border: "1px solid " + T.edge, borderRadius: 2,
            padding: "12px 14px", marginBottom: 10 }}>
            <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 6 }}>
              <span style={{ fontFamily: T.serif, fontSize: 16, flex: 1 }}>{r.world_title}</span>
              {r.report_count > 1 && (
                <span style={{ fontFamily: T.mono, fontSize: 11, color: T.clay }}>
                  {r.report_count} reports
                </span>
              )}
            </div>
            <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, lineHeight: 1.8, marginBottom: 10 }}>
              <div>{r.reason}</div>
              {r.detail && <div style={{ color: T.bone }}>{r.detail}</div>}
              <div>by @{r.owner_username ?? "unknown"} · {new Date(r.created_at).toLocaleDateString()}</div>
            </div>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              <Btn kind="danger" disabled={busy === r.id} onClick={() => act(r, true)}>
                Unpublish and close
              </Btn>
              <Btn disabled={busy === r.id} onClick={() => act(r, false)}>Leave it, close</Btn>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

