function ArtPresetList({ engine }) {
  const [rows, setRows] = useState(null);
  const [editing, setEditing] = useState(null);
  const [label, setLabel] = useState("");
  const [config, setConfig] = useState({});
  const [kind, setKind] = useState("room");
  const [defaultId, setDefaultId] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);

  const refresh = () => {
    loadArtPresets(engine).then(setRows).catch((e) => setError(e.message));
    loadDefaultArtPreset(engine).then(setDefaultId).catch(() => {});
  };
  useEffect(() => { refresh(); edit(null); }, [engine]);

  const edit = (row) => {
    setEditing(row);
    setLabel(row?.label ?? "");
    setConfig(row?.config ?? {});
    setKind("room");
    setError(null);
  };

  const save = async () => {
    setBusy(true); setError(null);
    try {
      await saveArtPreset({ id: editing?.id, engine, label, config, sortOrder: editing?.sort_order ?? (rows?.length ?? 0) });
      refresh();
      // Back to "New preset" mode, but the fields stay exactly as they are:
      // a saved preset is a reasonable starting point for the next one.
      // Only the explicit "+ New preset" button clears the form.
      setEditing(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const remove = async (row) => {
    setBusy(true); setError(null);
    try {
      await deleteArtPreset(row.id);
      refresh();
      if (editing?.id === row.id) edit(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const makeDefault = async (row) => {
    setBusy(true);
    try {
      await saveDefaultArtPreset(engine, row.id);
      setDefaultId(row.id);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  /* Clearing the default does not delete anything — it just means the
     Pictures tab's own "Default" button falls back to the platform's
     original wording again, the same as if no preset had ever been
     marked default at all. */
  const removeDefault = async () => {
    setBusy(true);
    try {
      await saveDefaultArtPreset(engine, null);
      setDefaultId(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const togglePublished = async (row) => {
    setBusy(true);
    try {
      await setArtPresetPublished(row.id, !row.published);
      setRows((rs) => rs.map((r) => r.id === row.id ? { ...r, published: !row.published } : r));
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const field = (key, patch) => setConfig((c) => ({ ...c, [key]: patch }));

  return (
    <div>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between",
        gap: 12, marginBottom: 20 }}>
        <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: 0, flex: 1 }}>
          A preset a creator can attach in the Pictures tab. Picking one there does not fill their own
          boxes — it lays this text underneath whatever they type, so their words and this preset's
          both reach the picture.
        </p>
        <Btn kind="solid" onClick={() => edit(null)} style={{ flexShrink: 0 }}>+ New preset</Btn>
      </div>

      {rows === null ? (
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
      ) : (
        <div style={{ marginBottom: 24 }}>
          {rows.map((r) => (
            <div key={r.id} style={{ border: "1px solid " + (defaultId === r.id ? T.ochre : T.edge),
              borderRadius: 2, padding: "10px 14px", marginBottom: 8,
              display: "flex", alignItems: "center", gap: 10 }}>
              <div style={{ fontFamily: T.serif, fontSize: 15, flex: 1, display: "flex", alignItems: "baseline", gap: 8 }}>
                {r.label}
                {defaultId === r.id && (
                  <span style={{ fontFamily: T.mono, fontSize: 10, color: T.ochre }}>default</span>
                )}
                {!r.published && (
                  <span style={{ fontFamily: T.mono, fontSize: 10, color: T.clay }}>unpublished — creators don't see this</span>
                )}
              </div>
              <Btn kind="ghost" disabled={busy} onClick={() => togglePublished(r)}>
                {r.published ? "unpublish" : "publish"}
              </Btn>
              {defaultId === r.id ? (
                <Btn kind="ghost" disabled={busy} onClick={removeDefault}>remove default</Btn>
              ) : (
                <Btn kind="ghost" disabled={busy} onClick={() => makeDefault(r)}>make default</Btn>
              )}
              <Btn kind="ghost" onClick={() => edit(r)}>edit</Btn>
              <Btn kind="danger" disabled={busy} onClick={() => remove(r)}>delete</Btn>
            </div>
          ))}
          {!rows.length && (
            <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>No presets yet.</p>
          )}
        </div>
      )}

      <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 18 }}>
        <div style={{ fontFamily: T.serif, fontSize: 16, marginBottom: 12 }}>
          {editing ? `Editing "${editing.label}"` : "New preset"}
        </div>

        <Field label="Preset label" hint="Shown to creators when they pick a preset in the Pictures tab.">
          <input style={inputStyle} value={label} onChange={(e) => setLabel(e.target.value)}
            placeholder="Warm and painterly" />
        </Field>

        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 16 }}>
          {KINDS.map((k) => (
            <button key={k.key} onClick={() => setKind(k.key)} className="pf-btn"
              style={{ background: "transparent", cursor: "pointer", padding: "7px 12px", borderRadius: 2,
                fontFamily: T.mono, fontSize: 12,
                color: kind === k.key ? T.bone : T.boneDim,
                border: "1px solid " + (kind === k.key ? T.ochre : T.edge) }}>
              {k.label}
            </button>
          ))}
        </div>

        <Field label="Art style" hint="Shared across every kind this preset touches.">
          <textarea value={config.style ?? ""} onChange={(e) => field("style", e.target.value)} rows={4}
            style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical" }} />
        </Field>

        <Field label={kind === "cover" ? "Framing for the splash screen" : `Framing for ${KIND_LABEL[kind] ?? kind}`}>
          <textarea value={config[kind] ?? ""} onChange={(e) => field(kind, e.target.value)} rows={3}
            style={{ ...inputStyle, fontSize: 13, lineHeight: 1.5, resize: "vertical" }} />
        </Field>

        {engine === "pixel" && (
          <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 16, marginTop: 4 }}>
            <p style={{ fontFamily: T.serif, fontSize: 13.5, color: T.boneDim, lineHeight: 1.6, margin: "0 0 14px" }}>
              The pixel/SDXL+LoRA engine's own numeric settings. These have no equivalent for a
              creator — nobody outside admin ever sees or changes them, alongside this preset's
              own prompt text above. Left blank, each falls through to the platform's own default.
            </p>

            <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginBottom: 4 }}>
              <Field label="LoRA scale" hint="Platform default: 0.5">
                <input type="number" step="0.05" style={{ ...inputStyle, width: 110 }}
                  value={config.lora_scale ?? ""} onChange={(e) => field("lora_scale", e.target.value)} />
              </Field>
              <Field label="Guidance scale" hint="Platform default: 7.5">
                <input type="number" step="0.5" style={{ ...inputStyle, width: 110 }}
                  value={config.guidance_scale ?? ""} onChange={(e) => field("guidance_scale", e.target.value)} />
              </Field>
              <Field label="Inference steps" hint="Platform default: 20">
                <input type="number" step="1" style={{ ...inputStyle, width: 110 }}
                  value={config.num_inference_steps ?? ""} onChange={(e) => field("num_inference_steps", e.target.value)} />
              </Field>
              <Field label="Safety checker version" hint="Platform default: v2">
                <input style={{ ...inputStyle, width: 110 }}
                  value={config.safety_checker_version ?? ""} onChange={(e) => field("safety_checker_version", e.target.value)} />
              </Field>
            </div>

            <Field label="Expand prompt" hint="Platform default: off">
              <div style={{ display: "flex", gap: 6 }}>
                {["", "true", "false"].map((v) => (
                  <button key={v || "default"} className="pf-btn"
                    onClick={() => field("expand_prompt", v)}
                    style={{ padding: "7px 12px", borderRadius: 2, cursor: "pointer", background: "transparent",
                      fontFamily: T.mono, fontSize: 12,
                      color: (config.expand_prompt ?? "") === v ? T.bone : T.boneDim,
                      border: "1px solid " + ((config.expand_prompt ?? "") === v ? T.ochre : T.edge) }}>
                    {v === "" ? "Platform default" : v === "true" ? "On" : "Off"}
                  </button>
                ))}
              </div>
            </Field>
          </div>
        )}

        {error && (
          <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginBottom: 12 }}>{error}</p>
        )}

        <div style={{ display: "flex", gap: 10 }}>
          <Btn kind="solid" disabled={busy || !label.trim()} onClick={save}>
            {editing ? "Save" : "Add"}
          </Btn>
          {editing && <Btn kind="ghost" onClick={() => edit(null)}>Cancel</Btn>}
        </div>
      </div>
    </div>
  );
}

/* What each token actually paints, so a bare word like "edge" or "ground"
   is not the only clue an admin has to go on. Textbox colours specifically
   come from ground (background), edge (border) and bone (text) — the
   thing this list exists to make findable, since those three names alone
   give no hint that they are the textbox setting. */
const T_KEYS = [
  ["ground",  "Page background — also the textbox background"],
  ["raised",  "Cards, panels, anything sitting above the page"],
  ["edge",    "Borders — also the textbox border"],
  ["bone",    "Main text — also the textbox text"],
  ["boneDim", "Secondary, quieter text"],
  ["ochre",   "The accent colour — selected states, links, highlights"],
  ["moss",    "Success, confirmation"],
  ["clay",    "Errors, warnings"],
];
const P_KEYS = [
  ["paper",     "Play surface background — the game itself"],
  ["paperDeep", "Panels within the game: the room picture frame, the settings sheet"],
  ["ink",       "Main text in the game"],
  ["inkSoft",   "Secondary, quieter text in the game"],
  ["ochre",     "The accent colour in the game — selected states, highlights"],
  ["rust",      "Errors, combat, anything that should read as trouble"],
  ["moss",      "Success, confirmation"],
];

function Swatch({ label, hint, value, onChange }) {
  const v = /^#[0-9a-fA-F]{3,8}$/.test(value || "") ? value : "#000000";
  return (
    <div style={{ marginBottom: 10 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <input type="color" value={v} onChange={(e) => onChange(e.target.value)}
          style={{ width: 30, height: 30, padding: 0, border: "1px solid " + T.edge, borderRadius: 2, cursor: "pointer", background: "none" }} />
        <input value={value ?? ""} onChange={(e) => onChange(e.target.value)}
          placeholder="inherits the platform default"
          style={{ ...inputStyle, flex: 1, fontFamily: T.mono, fontSize: 12, padding: "6px 8px" }} />
        <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, width: 62, flexShrink: 0 }}>{label}</span>
      </div>
      {hint && (
        <div style={{ fontFamily: T.mono, fontSize: 10, color: T.boneDim, marginTop: 3, marginLeft: 38 }}>
          {hint}
        </div>
      )}
    </div>
  );
}

const CRAWL_FONTS = {
  mono: { label: "Mono (platform default)", css: T.mono },
  imfell: { label: "IM Fell English", css: "'IM Fell English', Georgia, serif" },
  germania: { label: "Germania One", css: "'Germania One', serif" },
  vt323: { label: "VT323", css: "'VT323', monospace" },
  jacquard: { label: "Jacquard 12", css: "'Jacquard 12', serif" },
  coral: { label: "Coral Pixels", css: "'Coral Pixels', sans-serif" },
  jersey10: { label: "Jersey 10", css: "'Jersey 10', sans-serif" },
  jersey15: { label: "Jersey 15", css: "'Jersey 15', sans-serif" },
};
const STORY_CRAWL_RESET_DEFAULTS = { wordsPerSec: 2.9, fontSize: 3.00, font: "mono", color: "bone" };

function StoryCrawlTab() {
  const [visible, setVisible] = useState(null);
  const [settings, setSettings] = useState(null);
  const [error, setError] = useState(null);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    loadSetting("story_crawl_debug_visible").then((v) => setVisible(Boolean(v?.visible))).catch(() => setVisible(false));
    loadSetting("story_crawl_defaults").then((v) => setSettings({ ...STORY_CRAWL_RESET_DEFAULTS, ...v })).catch(() => setSettings(STORY_CRAWL_RESET_DEFAULTS));
  }, []);

  const toggleVisible = async () => {
    const next = !visible;
    setVisible(next); // optimistic
    try {
      await saveSetting("story_crawl_debug_visible", { visible: next });
    } catch (e) {
      setVisible(!next);
      setError(e.message);
    }
  };

  const write = async (next) => {
    setSettings(next);
    setError(null);
    try {
      await saveSetting("story_crawl_defaults", next);
      setSaved(true);
      setTimeout(() => setSaved(false), 1600);
    } catch (e) {
      setError(e.message);
    }
  };

  const resetToDefault = () => write(STORY_CRAWL_RESET_DEFAULTS);

  if (visible === null || !settings) return <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>;

  return (
    <div>
      <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim, lineHeight: 1.6, marginBottom: 20 }}>
        Controls the story crawl that plays on a game's details page. The debug block below sets the
        actual defaults everyone gets; the toggle above it controls whether that same block is also
        shown to players on every game, for further tuning later.
      </p>

      <Btn kind={visible ? "solid" : "quiet"} onClick={toggleVisible} style={{ marginBottom: 20 }}>
        {visible ? "Debug block is visible in games \u2014 click to hide" : "Show debug block in games"}
      </Btn>

      {/* Same block and wording as the temporary one in GameDetail.jsx —
          this one writes to the global app_settings defaults instead of
          a per-browser localStorage override. */}
      <div style={{ border: "1px dashed " + T.edge, borderRadius: 2, padding: 10, marginBottom: 12 }}>
        <div style={{ fontFamily: T.mono, fontSize: 10, color: T.clay, marginBottom: 8 }}>
          Crawl tuning (global default)
        </div>
        <label style={{ display: "block", fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 6 }}>
          Speed: {settings.wordsPerSec.toFixed(1)} words/sec
          <input type="range" min="0.3" max="5" step="0.1" value={settings.wordsPerSec}
            onChange={(e) => write({ ...settings, wordsPerSec: Number(e.target.value) })}
            style={{ display: "block", width: "100%" }} />
        </label>
        <label style={{ display: "block", fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
          Font size: {settings.fontSize.toFixed(2)}cqw (scales with frame width)
          <input type="range" min="1.5" max="6" step="0.05" value={settings.fontSize}
            onChange={(e) => write({ ...settings, fontSize: Number(e.target.value) })}
            style={{ display: "block", width: "100%" }} />
        </label>
        <label style={{ display: "block", fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginTop: 10 }}>
          Font
          <select value={settings.font} onChange={(e) => write({ ...settings, font: e.target.value })}
            style={{ ...inputStyle, display: "block", width: "100%", marginTop: 4 }}>
            {Object.entries(CRAWL_FONTS).map(([key, f]) => (
              <option key={key} value={key}>{f.label}</option>
            ))}
          </select>
        </label>
        <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginTop: 10, marginBottom: 4 }}>
          Color
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          {[["ochre", "Accent (ochre)"], ["bone", "Bone"]].map(([k, label]) => (
            <button key={k} className="pf-btn" onClick={() => write({ ...settings, color: k })}
              style={{ fontFamily: T.mono, fontSize: 11, padding: "5px 10px", cursor: "pointer", borderRadius: 2,
                background: "transparent", color: settings.color === k ? T.bone : T.boneDim,
                border: "1px solid " + (settings.color === k ? T.ochre : T.edge) }}>
              {label}
            </button>
          ))}
        </div>
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <Btn kind="ghost" onClick={resetToDefault}>Reset to default</Btn>
        {saved && <span style={{ fontFamily: T.mono, fontSize: 11, color: T.moss }}>saved</span>}
      </div>

      {error && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginTop: 12 }}>{error}</p>}
    </div>
  );
}

function AccessStageTab() {
  const [mode, setMode] = useState(null);
  const [stage, setStage] = useState(null);
  const [guestPlay, setGuestPlay] = useState(null);
  const [error, setError] = useState(null);
  const [saved, setSaved] = useState(false);

  const [query, setQuery] = useState("");
  const [results, setResults] = useState(null);
  const [searching, setSearching] = useState(false);

  useEffect(() => {
    loadCreationAccessMode().then(setMode).catch((e) => setError(e.message));
    loadPlatformStage().then(setStage).catch((e) => setError(e.message));
    loadSetting("guest_play_enabled").then((v) => setGuestPlay(v?.enabled === true)).catch((e) => setError(e.message));
  }, []);

  const flash = () => { setSaved(true); setTimeout(() => setSaved(false), 1600); };

  const setModeAndSave = async (m) => {
    setMode(m); // optimistic
    try { await saveCreationAccessMode(m); flash(); } catch (e) { setError(e.message); }
  };
  const setStageAndSave = async (s) => {
    setStage(s);
    try { await savePlatformStage(s); flash(); } catch (e) { setError(e.message); }
  };
  const setGuestPlayAndSave = async (enabled) => {
    setGuestPlay(enabled); // optimistic
    try { await saveSetting("guest_play_enabled", { enabled }); flash(); } catch (e) { setError(e.message); setGuestPlay(!enabled); }
  };

  const search = async () => {
    const q = query.trim();
    if (!q) return;
    setSearching(true); setError(null);
    try {
      // adminSearchUsers already returns isCreator — no second query needed.
      setResults(await adminSearchUsers(q));
    } catch (e) {
      setError(e.message);
    } finally {
      setSearching(false);
    }
  };

  const grant = async (userId, can) => {
    try {
      await adminSetCreator(userId, can);
      setResults((rows) => rows.map((r) => (r.id === userId ? { ...r, isCreator: can } : r)));
    } catch (e) {
      setError(e.message);
    }
  };

  return (
    <div>
      <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 10 }}>Who can create</div>
      <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, lineHeight: 1.6, marginBottom: 10 }}>
        "Everyone" means any signed-in account. "Restricted" hides the Create button from everyone
        except accounts individually granted access below — this is the switch a Patreon/Ko-fi/Buy Me
        a Coffee supporter's manual grant actually depends on.
      </p>
      <div style={{ display: "flex", gap: 6, marginBottom: 24 }}>
        {[["everyone", "Everyone"], ["restricted", "Restricted"]].map(([k, label]) => (
          <button key={k} className="pf-btn" onClick={() => setModeAndSave(k)}
            style={{ fontFamily: T.mono, fontSize: 12, padding: "7px 13px", cursor: "pointer", borderRadius: 2,
              background: mode === k ? T.ochre : "transparent", color: mode === k ? "#221D0C" : T.boneDim,
              border: "1px solid " + (mode === k ? T.ochre : T.edge) }}>
            {label}
          </button>
        ))}
      </div>

      <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 10 }}>Play without an account</div>
      <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, lineHeight: 1.6, marginBottom: 10 }}>
        "Must sign in" is the original flow — everyone without a session sees the sign-in page.
        "Guests may play" lets visitors browse and play without an account, with a Sign in button
        available whenever they want one.
      </p>
      <div style={{ display: "flex", gap: 6, marginBottom: 24 }}>
        {[[false, "Must sign in"], [true, "Guests may play"]].map(([v, label]) => (
          <button key={label} className="pf-btn" onClick={() => setGuestPlayAndSave(v)}
            style={{ fontFamily: T.mono, fontSize: 12, padding: "7px 13px", cursor: "pointer", borderRadius: 2,
              background: guestPlay === v ? T.ochre : "transparent", color: guestPlay === v ? "#221D0C" : T.boneDim,
              border: "1px solid " + (guestPlay === v ? T.ochre : T.edge) }}>
            {label}
          </button>
        ))}
      </div>

      <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 10 }}>Platform stage</div>
      <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, lineHeight: 1.6, marginBottom: 10 }}>
        Shown as a small label under the logo. "None" hides it entirely.
      </p>
      <div style={{ display: "flex", gap: 6, marginBottom: 12 }}>
        {[[null, "None"], ["alpha", "Alpha"], ["beta", "Beta"], ["live", "Live"]].map(([k, label]) => (
          <button key={label} className="pf-btn" onClick={() => setStageAndSave(k)}
            style={{ fontFamily: T.mono, fontSize: 12, padding: "7px 13px", cursor: "pointer", borderRadius: 2,
              background: stage === k ? T.ochre : "transparent", color: stage === k ? "#221D0C" : T.boneDim,
              border: "1px solid " + (stage === k ? T.ochre : T.edge) }}>
            {label}
          </button>
        ))}
      </div>
      {saved && <p style={{ fontFamily: T.mono, fontSize: 11, color: T.moss, marginBottom: 20 }}>saved</p>}

      <div style={{ fontFamily: T.serif, fontSize: 15, marginTop: 10, marginBottom: 10 }}>
        Grant or revoke individual create access
      </div>
      <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <input value={query} onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && search()}
          placeholder="Search by username or email" style={{ ...inputStyle, flex: 1 }} />
        <Btn kind="ghost" onClick={search} disabled={searching}>{searching ? "Searching\u2026" : "Search"}</Btn>
      </div>
      {results && (
        results.length === 0 ? (
          <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>No matches.</p>
        ) : (
          <div style={{ border: "1px solid " + T.edge, borderRadius: 2 }}>
            {results.map((r) => (
              <div key={r.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 12px",
                borderBottom: "1px solid " + T.edge, fontFamily: T.mono, fontSize: 12 }}>
                <div style={{ flex: 1 }}>{r.name || r.username}</div>
                <Btn kind={r.isCreator ? "solid" : "ghost"} onClick={() => grant(r.id, !r.isCreator)}>
                  {r.isCreator ? "Revoke" : "Grant"}
                </Btn>
              </div>
            ))}
          </div>
        )
      )}

      {error && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginTop: 16 }}>{error}</p>}
    </div>
  );
}

