const NAME_SCREEN_DEFAULTS = { theme: "current", labelWeight: "bold", glow: "default", color: "#4aff6e" };

function NameScreenThemeTab() {
  const [settings, setSettings] = useState(null);
  const [error, setError] = useState(null);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    loadSetting("guest_name_screen")
      .then((v) => setSettings({ ...NAME_SCREEN_DEFAULTS, ...v }))
      .catch(() => setSettings(NAME_SCREEN_DEFAULTS)); // no row saved yet — a normal, expected case, not an error
  }, []);

  const flash = () => { setSaved(true); setTimeout(() => setSaved(false), 1600); };

  const write = async (next) => {
    setSettings(next); // optimistic
    try { await saveSetting("guest_name_screen", next); flash(); } catch (e) { setError(e.message); }
  };

  if (!settings) return <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>;

  const Choice = ({ options, value, onPick }) => (
    <div style={{ display: "flex", gap: 6, marginBottom: 24 }}>
      {options.map(([v, label]) => (
        <button key={v} className="pf-btn" onClick={() => onPick(v)}
          style={{ fontFamily: T.mono, fontSize: 12, padding: "7px 13px", cursor: "pointer", borderRadius: 2,
            background: value === v ? T.ochre : "transparent", color: value === v ? "#221D0C" : T.boneDim,
            border: "1px solid " + (value === v ? T.ochre : T.edge) }}>
          {label}
        </button>
      ))}
    </div>
  );

  return (
    <div>
      <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, lineHeight: 1.6, marginBottom: 16 }}>
        Controls the "What is your name?" screen a guest sees before playing.
      </p>

      <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 10 }}>Theme</div>
      <Choice value={settings.theme} onPick={(theme) => write({ ...settings, theme })}
        options={[["current", "Current"], ["retro", "Retro"]]} />
      <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginTop: -18, marginBottom: 24 }}>
        "Retro" adds TV scanlines over the whole screen. Independent of the glow setting below.
      </p>

      <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 10 }}>"What is your name?" label</div>
      <Choice value={settings.labelWeight} onPick={(labelWeight) => write({ ...settings, labelWeight })}
        options={[["normal", "Normal"], ["bold", "Bold"]]} />

      <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 10 }}>Text glow</div>
      <Choice value={settings.glow} onPick={(glow) => write({ ...settings, glow })}
        options={[["default", "Default"], ["glow", "Glow"]]} />
      <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginTop: -18, marginBottom: 24 }}>
        When on, the label and the typed name pulse with the same glow intensity.
      </p>

      <div style={{ fontFamily: T.serif, fontSize: 15, marginBottom: 10 }}>Text color</div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 20 }}>
        <input type="color" value={settings.color}
          onChange={(e) => write({ ...settings, color: e.target.value })}
          style={{ width: 44, height: 32, padding: 0, border: "1px solid " + T.edge, borderRadius: 2, cursor: "pointer", background: "none" }} />
        <span style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>{settings.color}</span>
      </div>

      {saved && <p style={{ fontFamily: T.mono, fontSize: 11, color: T.moss }}>saved</p>}
      {error && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay }}>{error}</p>}
    </div>
  );
}

function OverallThemeTab() {
  const [rows, setRows] = useState(null);
  const [editing, setEditing] = useState(null);
  const [label, setLabel] = useState("");
  const [tOv, setTOv] = useState({});
  const [pOv, setPOv] = useState({});
  const [defaultId, setDefaultId] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);

  const refresh = () => {
    loadThemes().then(setRows).catch((e) => setError(e.message));
    loadDefaultTheme().then(setDefaultId).catch(() => {});
  };
  useEffect(() => { refresh(); }, []);

  const edit = (row) => {
    setEditing(row);
    setLabel(row?.label ?? "");
    setTOv(row?.t_overrides ?? {});
    setPOv(row?.p_overrides ?? {});
    setError(null);
  };

  const save = async () => {
    setBusy(true); setError(null);
    try {
      await saveTheme({ id: editing?.id, label, tOverrides: tOv, pOverrides: pOv, sortOrder: editing?.sort_order ?? (rows?.length ?? 0) });
      refresh();
      // Fields stay as they are, same reasoning as the art preset editor:
      // a saved theme is a reasonable starting point for the next one.
      setEditing(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const remove = async (row) => {
    setBusy(true); setError(null);
    try {
      await deleteTheme(row.id);
      refresh();
      if (editing?.id === row.id) edit(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const makeDefault = async (row) => {
    setBusy(true);
    try {
      await saveDefaultTheme(row.id);
      setDefaultId(row.id);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const removeThemeDefault = async () => {
    setBusy(true);
    try {
      await saveDefaultTheme(null);
      setDefaultId(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between",
        gap: 12, marginBottom: 12 }}>
        <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: 0, flex: 1 }}>
          Colour tokens, not CSS — the app has none to swap. Whichever theme is marked default here
          replaces these colours for everyone, on load, the moment they open the site. An empty box
          leaves that one colour at the platform default rather than overriding it.
        </p>
        <Btn kind="solid" onClick={() => edit(null)} style={{ flexShrink: 0 }}>+ New preset</Btn>
      </div>

      <p style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, lineHeight: 1.7, margin: "0 0 20px" }}>
        Only reaches a signed-in visitor right now — the tables this reads are authenticated-only,
        same as every other preset system. A logged-out visitor still sees the platform default.
      </p>

      {rows === null ? (
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
      ) : (
        <div style={{ marginBottom: 24 }}>
          {rows.map((r) => (
            <div key={r.id} style={{ border: "1px solid " + (defaultId === r.id ? T.ochre : T.edge),
              borderRadius: 2, padding: "10px 14px", marginBottom: 8,
              display: "flex", alignItems: "center", gap: 10 }}>
              <div style={{ display: "flex", gap: 3, flexShrink: 0 }}>
                {[r.t_overrides?.ochre ?? LIVE_T.ochre, r.t_overrides?.ground ?? LIVE_T.ground,
                  r.t_overrides?.bone ?? LIVE_T.bone].map((c, i) => (
                  <span key={i} style={{ width: 14, height: 14, borderRadius: 2, background: c,
                    border: "1px solid " + T.edge }} />
                ))}
              </div>
              <div style={{ fontFamily: T.serif, fontSize: 15, flex: 1, display: "flex", alignItems: "baseline", gap: 8 }}>
                {r.label}
                {defaultId === r.id && (
                  <span style={{ fontFamily: T.mono, fontSize: 10, color: T.ochre }}>default</span>
                )}
              </div>
              {defaultId === r.id ? (
                <Btn kind="ghost" disabled={busy} onClick={removeThemeDefault}>remove default</Btn>
              ) : (
                <Btn kind="ghost" disabled={busy} onClick={() => makeDefault(r)}>make default</Btn>
              )}
              <Btn kind="ghost" onClick={() => edit(r)}>edit</Btn>
              <Btn kind="danger" disabled={busy} onClick={() => remove(r)}>delete</Btn>
            </div>
          ))}
          {!rows.length && (
            <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>No themes yet.</p>
          )}
        </div>
      )}

      <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 18 }}>
        <div style={{ fontFamily: T.serif, fontSize: 16, marginBottom: 12 }}>
          {editing ? `Editing "${editing.label}"` : "New theme"}
        </div>

        <Field label="Theme label">
          <input style={inputStyle} value={label} onChange={(e) => setLabel(e.target.value)}
            placeholder="Old Ascentery" />
        </Field>

        <div style={{ display: "flex", gap: 24, flexWrap: "wrap" }}>
          <div style={{ minWidth: 260 }}>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 8 }}>
              Catalog (T) — the browsing, editing, admin screens
            </div>
            {T_KEYS.map(([k, hint]) => (
              <Swatch key={k} label={k} hint={hint} value={tOv[k]}
                onChange={(v) => setTOv((o) => ({ ...o, [k]: v || undefined }))} />
            ))}
          </div>
          <div style={{ minWidth: 260 }}>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 8 }}>
              Play surface (P) — the game itself
            </div>
            {P_KEYS.map(([k, hint]) => (
              <Swatch key={k} label={k} hint={hint} value={pOv[k]}
                onChange={(v) => setPOv((o) => ({ ...o, [k]: v || undefined }))} />
            ))}
          </div>
        </div>

        {error && (
          <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, margin: "12px 0" }}>{error}</p>
        )}

        <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
          <Btn kind="solid" disabled={busy || !label.trim()} onClick={save}>
            {editing ? "Save" : "Add"}
          </Btn>
          {editing && <Btn kind="ghost" onClick={() => edit(null)}>Cancel</Btn>}
        </div>
      </div>
    </div>
  );
}

function UsernamesTab() {
  const [words, setWords] = useState(null);
  const [newWord, setNewWord] = useState("");
  const [substrings, setSubstrings] = useState(null);
  const [newSubstring, setNewSubstring] = useState("");
  const [minLength, setMinLength] = useState(null);
  const [minLengthSaved, setMinLengthSaved] = useState(false);
  const [prompt, setPrompt] = useState("");
  const [promptLoaded, setPromptLoaded] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [saved, setSaved] = useState(false);

  const refresh = () => {
    loadReservedWords().then(setWords).catch((e) => setError(e.message));
  };
  const refreshSubstrings = () => {
    loadForbiddenSubstrings().then(setSubstrings).catch((e) => setError(e.message));
  };
  useEffect(() => {
    refresh();
    refreshSubstrings();
    loadUsernameMinLength().then(setMinLength).catch(() => setMinLength(5));
    loadUsernamePrompt().then((t) => { setPrompt(t ?? ""); setPromptLoaded(true); }).catch(() => setPromptLoaded(true));
  }, []);

  const add = async () => {
    const w = newWord.trim().toLowerCase();
    if (!w) return;
    setBusy(true); setError(null);
    try {
      await addReservedWord(w);
      setNewWord("");
      refresh();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const remove = async (w) => {
    setBusy(true); setError(null);
    try {
      await removeReservedWord(w);
      refresh();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const addSubstring = async () => {
    const w = newSubstring.trim().toLowerCase();
    if (!w) return;
    setBusy(true); setError(null);
    try {
      await addForbiddenSubstring(w);
      setNewSubstring("");
      refreshSubstrings();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const removeSubstring = async (w) => {
    setBusy(true); setError(null);
    try {
      await removeForbiddenSubstring(w);
      refreshSubstrings();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const saveMinLength = async () => {
    setBusy(true); setError(null);
    try {
      await saveUsernameMinLength(Number(minLength) || 5);
      setMinLengthSaved(true);
      setTimeout(() => setMinLengthSaved(false), 1600);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const savePrompt = async () => {
    setBusy(true); setError(null);
    try {
      await saveUsernamePrompt(prompt.trim());
      setSaved(true);
      setTimeout(() => setSaved(false), 1600);
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 24px" }}>
        Three free, instant checks, all editable below — minimum length, reserved words (a name is
        rejected only if it exactly equals one of these), and forbidden substrings (rejected if it
        contains one of these anywhere, so "psyblade1" and "ipsyblade" are caught by a "psyblade"
        entry just as much as "psyblade" itself is). The AI moderation prompt further down is what
        gets asked only once a name passes every one of these — vulgarity, impersonation, anything
        a plain list can't catch. Character set (letters and numbers only) is the one fixed rule not
        editable here.
      </p>

      <div style={{ marginBottom: 32 }}>
        <div style={{ fontFamily: T.serif, fontSize: 17, marginBottom: 12 }}>Minimum length</div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <input type="number" min={1} style={{ ...inputStyle, width: 80 }}
            value={minLength ?? ""} onChange={(e) => setMinLength(e.target.value)} />
          <Btn kind="solid" disabled={busy || minLength == null} onClick={saveMinLength}>
            {minLengthSaved ? "Saved" : "Save"}
          </Btn>
        </div>
      </div>

      <div style={{ marginBottom: 32 }}>
        <div style={{ fontFamily: T.serif, fontSize: 17, marginBottom: 12 }}>Reserved words</div>
        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <input style={{ ...inputStyle, flex: 1 }} value={newWord} onChange={(e) => setNewWord(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && add()} placeholder="dashboard" />
          <Btn kind="solid" disabled={busy || !newWord.trim()} onClick={add}>Add</Btn>
        </div>

        {words === null ? (
          <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
            {words.map((w) => (
              <span key={w} style={{ display: "flex", alignItems: "center", gap: 6,
                border: "1px solid " + T.edge, borderRadius: 2, padding: "5px 10px",
                fontFamily: T.mono, fontSize: 12, color: T.bone }}>
                {w}
                <button onClick={() => remove(w)} disabled={busy} className="pf-btn"
                  style={{ background: "none", border: "none", padding: 0, cursor: "pointer", color: T.clay, fontSize: 13 }}>
                  {"\u00d7"}
                </button>
              </span>
            ))}
            {!words.length && <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>Nothing reserved yet.</p>}
          </div>
        )}
      </div>

      <div style={{ marginBottom: 32 }}>
        <div style={{ fontFamily: T.serif, fontSize: 17, marginBottom: 12 }}>Forbidden substrings</div>
        <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 14, lineHeight: 1.6 }}>
          Rejected if a name contains this anywhere, not just an exact match — separate from reserved
          words above for exactly that reason.
        </p>
        <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
          <input style={{ ...inputStyle, flex: 1 }} value={newSubstring} onChange={(e) => setNewSubstring(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && addSubstring()} placeholder="psyblade" />
          <Btn kind="solid" disabled={busy || !newSubstring.trim()} onClick={addSubstring}>Add</Btn>
        </div>

        {substrings === null ? (
          <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
            {substrings.map((w) => (
              <span key={w} style={{ display: "flex", alignItems: "center", gap: 6,
                border: "1px solid " + T.edge, borderRadius: 2, padding: "5px 10px",
                fontFamily: T.mono, fontSize: 12, color: T.bone }}>
                {w}
                <button onClick={() => removeSubstring(w)} disabled={busy} className="pf-btn"
                  style={{ background: "none", border: "none", padding: 0, cursor: "pointer", color: T.clay, fontSize: 13 }}>
                  {"\u00d7"}
                </button>
              </span>
            ))}
            {!substrings.length && <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>Nothing forbidden yet.</p>}
          </div>
        )}
      </div>

      <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 24 }}>
        <div style={{ fontFamily: T.serif, fontSize: 17, marginBottom: 12 }}>AI moderation prompt</div>
        {!promptLoaded ? (
          <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
        ) : (
          <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} rows={10}
            placeholder="Leave blank to use the platform's own built-in instructions."
            style={{ ...inputStyle, fontFamily: T.mono, fontSize: 12.5, lineHeight: 1.6, resize: "vertical" }} />
        )}
        <p style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, margin: "8px 0 14px" }}>
          Clearing this and saving falls back to the platform's own built-in wording — it never sends
          nothing to the model, just the default instructions instead of a customised set.
        </p>

        {error && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginBottom: 12 }}>{error}</p>}

        <Btn kind="solid" disabled={busy} onClick={savePrompt}>{saved ? "saved" : "Save"}</Btn>
      </div>
    </div>
  );
}

function UsersTab() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [creditInputs, setCreditInputs] = useState({});   // { [userId]: "500" }

  const search = async () => {
    setBusy(true); setError(null);
    try {
      setResults(await adminSearchUsers(query.trim()));
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const toggleCreator = async (u) => {
    setBusy(true); setError(null);
    try {
      await adminSetCreator(u.id, !u.isCreator);
      setResults((rs) => rs.map((r) => r.id === u.id ? { ...r, isCreator: !r.isCreator } : r));
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const addCredits = async (u) => {
    const raw = creditInputs[u.id];
    const cents = Math.round(Number(raw) * 100);
    if (!raw || !Number.isFinite(cents) || cents === 0) {
      setError("Enter a dollar amount, e.g. 5 or -2.50.");
      return;
    }
    setBusy(true); setError(null);
    try {
      const newBalance = await adminAddCredits(u.id, cents);
      setResults((rs) => rs.map((r) => r.id === u.id ? { ...r, balance: newBalance } : r));
      setCreditInputs((c) => ({ ...c, [u.id]: "" }));
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 20px" }}>
        Search matches part of a display name, username, or email. Toggling creator status and
        adjusting credits both take effect immediately — there is no confirmation step, since this is
        an admin-only tool already.
      </p>

      <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
        <input style={{ ...inputStyle, flex: 1 }} value={query} onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && search()} placeholder="wei, @lily-4356, someone@example.com" />
        <Btn kind="solid" disabled={busy} onClick={search}>Search</Btn>
      </div>

      {error && <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginBottom: 16 }}>{error}</p>}

      {results !== null && (
        !results.length ? (
          <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>No matches.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            {results.map((u) => (
              <div key={u.id} style={{ border: "1px solid " + T.edge, borderRadius: 4, padding: 14 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 4 }}>
                  <div style={{ fontFamily: T.serif, fontSize: 16 }}>{u.name}</div>
                  <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>{money(u.balance)}</div>
                </div>
                <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, marginBottom: 12 }}>
                  {u.username ? `@${u.username} \u00b7 ` : ""}{u.email}{u.isAdmin ? " \u00b7 admin" : ""}
                </div>

                <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                  <Btn kind={u.isCreator ? "ghost" : "solid"} disabled={busy} onClick={() => toggleCreator(u)}>
                    {u.isCreator ? "Remove creator" : "Make creator"}
                  </Btn>
                  <input style={{ ...inputStyle, width: 100 }} value={creditInputs[u.id] ?? ""}
                    onChange={(e) => setCreditInputs((c) => ({ ...c, [u.id]: e.target.value }))}
                    placeholder="5.00" />
                  <Btn kind="ghost" disabled={busy} onClick={() => addCredits(u)}>Add credits</Btn>
                </div>
              </div>
            ))}
          </div>
        )
      )}
    </div>
  );
}

// ─── Marketing: Trailers ──────────────────────────────────────────────────────

function TrailersTab() {
  const [trailers, setTrailers] = useState(null);
  const [error, setError]       = useState(null);
  const [busy, setBusy]         = useState(false);
  // Inline editor: null = none open, "new" = new row, id = editing that row
  const [editing, setEditing]   = useState(null);
  const [form, setForm]         = useState({});
  const [uploadingPoster, setUploadingPoster] = useState(false);
  const [uploadingVideo, setUploadingVideo]   = useState(false);
  const [videoProgress, setVideoProgress]     = useState(null);

  useEffect(() => {
    loadTrailers().then(setTrailers).catch((e) => setError(e.message));
  }, []);

  const reload = () => loadTrailers().then(setTrailers).catch((e) => setError(e.message));

  const openNew = () => {
    setEditing("new");
    setForm({ label: "", sourceUrl: "", posterUrl: "", durationLabel: "", sortOrder: 0 });
    setError(null);
  };

  const openEdit = (t) => {
    setEditing(t.id);
    setForm({ label: t.label, sourceUrl: t.sourceUrl ?? "", posterUrl: t.posterUrl ?? "",
              durationLabel: t.durationLabel ?? "", sortOrder: t.sortOrder ?? 0 });
    setError(null);
  };

  const cancelEdit = () => { setEditing(null); setForm({}); };

  const save = async () => {
    setBusy(true); setError(null);
    try {
      await saveTrailer({ ...(editing !== "new" ? { id: editing } : {}), ...form });
      await reload();
      setEditing(null);
    } catch (e) { setError(e.message); }
    finally { setBusy(false); }
  };

  const remove = async (id) => {
    if (!window.confirm("Delete this trailer?")) return;
    setBusy(true); setError(null);
    try { await deleteTrailer(id); await reload(); }
    catch (e) { setError(e.message); }
    finally { setBusy(false); }
  };

  const activate = async (id) => {
    setBusy(true); setError(null);
    try { await setActiveTrailer(id); await reload(); }
    catch (e) { setError(e.message); }
    finally { setBusy(false); }
  };

  const handlePosterUpload = async (file) => {
    if (!file) return;
    setUploadingPoster(true); setError(null);
    try {
      const url = await uploadMarketingPoster(file, editing === "new" ? "" : editing);
      setForm((f) => ({ ...f, posterUrl: url }));
    } catch (e) { setError(e.message); }
    finally { setUploadingPoster(false); }
  };

  const handleVideoUpload = async (file) => {
    if (!file) return;
    if (editing === "new") {
      setError("Save the trailer row first, then upload the video.");
      return;
    }
    setUploadingVideo(true); setVideoProgress("uploading…"); setError(null);
    try {
      const url = await uploadMarketingVideo(file, editing);
      setForm((f) => ({ ...f, sourceUrl: url }));
      setVideoProgress(null);
    } catch (e) { setError(e.message); setVideoProgress(null); }
    finally { setUploadingVideo(false); }
  };

  if (!trailers) return <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>{error || "Loading…"}</p>;

  return (
    <div>
      <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim, marginBottom: 20 }}>
        The active trailer plays as the hero on the landing page and the home screen
        (for users with no recent plays). Only one trailer is active at a time.
      </p>

      {error && <p style={{ fontFamily: T.mono, fontSize: 12, color: "#c0392b", marginBottom: 12 }}>{error}</p>}

      <Btn onClick={openNew} disabled={busy || editing !== null} style={{ marginBottom: 20 }}>+ Add trailer</Btn>

      {editing === "new" && (
        <TrailerForm form={form} setForm={setForm} busy={busy}
          uploadingPoster={uploadingPoster} uploadingVideo={uploadingVideo}
          videoProgress={videoProgress} isNew
          onPosterUpload={handlePosterUpload}
          onVideoUpload={handleVideoUpload}
          onSave={save} onCancel={cancelEdit} />
      )}

      {trailers.length === 0 && editing !== "new" && (
        <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>No trailers yet.</p>
      )}

      {trailers.map((t) => (
        <div key={t.id} style={{ borderBottom: `1px solid ${T.edge}`, paddingBottom: 16, marginBottom: 16 }}>
          {editing === t.id ? (
            <TrailerForm form={form} setForm={setForm} busy={busy}
              uploadingPoster={uploadingPoster} uploadingVideo={uploadingVideo}
              videoProgress={videoProgress}
              onPosterUpload={handlePosterUpload}
              onVideoUpload={handleVideoUpload}
              onSave={save} onCancel={cancelEdit} />
          ) : (
            <div>
              <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 6 }}>
                <span style={{ fontFamily: T.serif, fontSize: 15 }}>{t.label || "(untitled)"}</span>
                {t.isActive && (
                  <span style={{ fontFamily: T.mono, fontSize: 10, color: T.ochre,
                    border: `1px solid ${T.ochre}`, borderRadius: 2, padding: "1px 5px" }}>
                    ACTIVE
                  </span>
                )}
                {t.durationLabel && (
                  <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>{t.durationLabel}</span>
                )}
              </div>
              {t.posterUrl && (
                <img src={t.posterUrl} alt="poster"
                  style={{ height: 80, objectFit: "cover", borderRadius: 2, marginBottom: 8, display: "block" }} />
              )}
              {t.sourceUrl && (
                <p style={{ fontFamily: T.mono, fontSize: 10, color: T.boneDim, marginBottom: 8,
                  wordBreak: "break-all" }}>{t.sourceUrl}</p>
              )}
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <Btn kind="ghost" disabled={busy} onClick={() => openEdit(t)}>Edit</Btn>
                {!t.isActive && <Btn kind="solid" disabled={busy} onClick={() => activate(t.id)}>Set active</Btn>}
                <Btn kind="ghost" disabled={busy} onClick={() => remove(t.id)}
                  style={{ color: T.clay }}>Delete</Btn>
              </div>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

function TrailerForm({ form, setForm, busy, uploadingPoster, uploadingVideo,
                       videoProgress, isNew, onPosterUpload, onVideoUpload, onSave, onCancel }) {
  const f = (k) => (v) => setForm((s) => ({ ...s, [k]: v }));
  return (
    <div style={{ background: T.raised, border: `1px solid ${T.edge}`, borderRadius: 4,
      padding: 16, marginBottom: 16 }}>
      <Field label="Label (internal name)" value={form.label ?? ""} onChange={f("label")} />
      <Field label="Duration label (e.g. 1:32)" value={form.durationLabel ?? ""} onChange={f("durationLabel")} />
      <Field label="Video URL (paste or upload below)" value={form.sourceUrl ?? ""} onChange={f("sourceUrl")} />

      {!isNew && (
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 6 }}>
            Upload trailer video to B2 (overwrites URL above):
          </div>
          <label className="pf-btn" style={{ display: "inline-block", cursor: uploadingVideo ? "default" : "pointer",
            opacity: uploadingVideo ? 0.6 : 1, fontFamily: T.mono, fontSize: 12,
            border: `1px solid ${T.edge}`, borderRadius: 2, padding: "6px 12px" }}>
            {videoProgress ?? (uploadingVideo ? "uploading…" : "choose video file")}
            <input type="file" accept="video/mp4,video/webm,video/mov" style={{ display: "none" }}
              disabled={uploadingVideo || busy}
              onChange={(e) => onVideoUpload(e.target.files?.[0])} />
          </label>
        </div>
      )}

      <Field label="Poster URL (paste or upload below)" value={form.posterUrl ?? ""} onChange={f("posterUrl")} />
      <div style={{ marginBottom: 14 }}>
        <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 6 }}>
          Upload poster image:
        </div>
        <label className="pf-btn" style={{ display: "inline-block", cursor: uploadingPoster ? "default" : "pointer",
          opacity: uploadingPoster ? 0.6 : 1, fontFamily: T.mono, fontSize: 12,
          border: `1px solid ${T.edge}`, borderRadius: 2, padding: "6px 12px" }}>
          {uploadingPoster ? "uploading…" : "choose image"}
          <input type="file" accept="image/png,image/jpeg,image/webp" style={{ display: "none" }}
            disabled={uploadingPoster || busy}
            onChange={(e) => onPosterUpload(e.target.files?.[0])} />
        </label>
        {form.posterUrl && (
          <img src={form.posterUrl} alt="poster preview"
            style={{ height: 60, objectFit: "cover", borderRadius: 2, marginLeft: 10, verticalAlign: "middle" }} />
        )}
      </div>

      <div style={{ display: "flex", gap: 8 }}>
        <Btn disabled={busy || uploadingPoster || uploadingVideo} onClick={onSave}>
          {isNew ? "Create" : "Save"}
        </Btn>
        <Btn kind="ghost" disabled={busy} onClick={onCancel}>Cancel</Btn>
      </div>
    </div>
  );
}

// ─── Marketing: Waitlist ──────────────────────────────────────────────────────

function WaitlistTab() {
  const [entries, setEntries] = useState(null);
  const [error, setError]     = useState(null);

  useEffect(() => {
    loadWaitlist().then(setEntries).catch((e) => setError(e.message));
  }, []);

  if (!entries) return <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>{error || "Loading…"}</p>;

  return (
    <div>
      <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim, marginBottom: 20 }}>
        {entries.length} {entries.length === 1 ? "entry" : "entries"} — newest first.
      </p>
      {error && <p style={{ fontFamily: T.mono, fontSize: 12, color: "#c0392b", marginBottom: 12 }}>{error}</p>}
      {entries.length === 0 && (
        <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>No waitlist entries yet.</p>
      )}
      <div style={{ display: "flex", flexDirection: "column", gap: 1 }}>
        {entries.map((e) => (
          <div key={e.id} style={{ display: "flex", gap: 16, alignItems: "baseline",
            padding: "8px 0", borderBottom: `1px solid ${T.edge}` }}>
            <span style={{ fontFamily: T.mono, fontSize: 12, flex: 1, wordBreak: "break-all" }}>{e.email}</span>
            {e.source && e.source !== "landing" && (
              <span style={{ fontFamily: T.mono, fontSize: 10, color: T.boneDim }}>{e.source}</span>
            )}
            {e.invited_at && (
              <span style={{ fontFamily: T.mono, fontSize: 10, color: T.ochre }}>invited</span>
            )}
            <span style={{ fontFamily: T.mono, fontSize: 10, color: T.boneDim, whiteSpace: "nowrap" }}>
              {new Date(e.created_at).toLocaleDateString()}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
