// Undoes 404.html's redirect: GitHub Pages has no server-side routing,
// so a direct hit on /johndoe first lands on 404.html (see that file's
// own comment for why), which bounces back here with the real path
// carried in a query string instead. This restores the real path via
// replaceState before anything below reads it, so it's transparent to
// the rest of the app — usernameFromPath() never needs to know this
// redirect happened at all. Runs once, at module load, before React
// mounts, not inside the component itself.
if (typeof window !== "undefined") {
  const params = new URLSearchParams(window.location.search);
  const redirected = params.get("spa_redirect");
  if (redirected) window.history.replaceState({}, "", redirected);
}

// URL segment -> the view.name it actually opens, for every real,
// built view a person might reasonably link to directly. Multiple
// segments can point at the same view (aliases) — "home" is this app's
// own internal name for what its UI actually calls "Recently Played",
// so both wordings work as a URL.
//
// Deliberately NOT included here, and why:
//  - "game"/"edit": these take an id, not a static word — a separate
//    slug-based scheme for individual games is its own piece of work.
//  - "username": the view for *choosing* a username is an in-app flow,
//    never something meant to be linked to directly.
//  - "creatorprofile": that's what a bare /<username> already opens —
//    giving the word itself a second, static meaning would conflict.
const ROUTE_ALIASES = {
  browse: "browse",
  home: "home", recent: "home", recently_played: "home",
  mine: "mine",
  friends: "friends", friend: "friends",
  profile: "profile",
  creator: "creator",
  admin: "admin",
  create: "create",
  avatar: "avatar",
  settings: "settings",
  support: "support", support_our_project: "support",
  signin: "auth", login: "auth",
};

// The canonical URL go() writes back for each view — picked as the
// clearest of that view's own aliases above, not necessarily the first
// one someone might type.
const CANONICAL_URL = {
  browse: "/browse", home: "/", mine: "/mine", friends: "/friends",
  profile: "/profile", creator: "/creator", admin: "/admin",
  create: "/create", avatar: "/avatar", settings: "/settings",
  support: "/support_our_project",
  auth: "/signin",
};

// Visiting these actually signs the person out — an action, not a page
// to render — rather than a view this router would otherwise open.
const SIGNOUT_WORDS = new Set(["signout", "logout"]);

// Words with no built feature behind them yet — or, for reset/
// reset_password specifically, a real view that exists but is normally
// only entered through a genuine password-recovery session, not
// ordinary navigation; routing straight to it from a plain visit risks
// showing a broken-looking form with no recovery session behind it,
// which isn't confirmed safe without ResetPasswordPage.jsx in hand.
// Reserved either way, so nobody can claim these as a username, but a
// plain visit falls through to the ordinary default view, same as any
// other unrecognized path that isn't a username either.
const RESERVED_NO_ROUTE_YET = new Set([
  "faq", "tos", "community",
  "trending", "most_played", "latest", "newest",
  "reset", "reset_password",
]);

// Every word a URL's first segment must never be read as a username —
// every real route's own aliases, the sign-out words, the reserved-but-
// unbuilt words above, plus the view names that exist internally but
// were deliberately left out of ROUTE_ALIASES for the reasons noted
// there. Registration already blocks all of these via
// reserved_usernames, so no existing or future username can collide
// with any of them.
const KNOWN_ROUTES = new Set([
  ...Object.keys(ROUTE_ALIASES),
  ...SIGNOUT_WORDS,
  ...RESERVED_NO_ROUTE_YET,
  "game", "edit", "username", "creatorprofile", "play", "resetpassword", "purchase-successful", "guestname", "support", "support_our_project",
]);

// Reads the very first path segment off the current URL, lowercased —
// the same casing convention usernames already use (citext), and how
// KNOWN_ROUTES above is written. Returns null for the root path or
// anything matching a real route, so the caller knows to fall back to
// the normal default view instead.
function usernameFromPath() {
  if (typeof window === "undefined") return null;
  const segment = window.location.pathname.replace(/^\/+|\/+$/g, "").split("/")[0];
  if (!segment || KNOWN_ROUTES.has(segment.toLowerCase())) return null;
  return segment;
}

// The view the current URL's first path segment actually opens, or
// null if it isn't a recognized route at all (the root path, an
// unrecognized word, or a username — usernameFromPath handles that
// last case separately).
function viewFromPath() {
  if (typeof window === "undefined") return null;
  const segment = window.location.pathname.replace(/^\/+|\/+$/g, "").split("/")[0].toLowerCase();
  const name = ROUTE_ALIASES[segment];
  return name ? { name } : null;
}

// A path shaped /username/gamename — the game's own slug, resolved
// against its owner's username (see loadGameBySlug's own comment for
// why this is a two-step lookup, not a single embedded query). Returns
// null unless there really are exactly two segments and the first
// isn't a known route — a bare /username alone is handled separately,
// by usernameFromPath.
function gameSlugFromPath() {
  if (typeof window === "undefined") return null;
  const parts = window.location.pathname.replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
  // Accept /username/slug, /username/slug/play, /username/slug/edit
  if (parts.length !== 2 && parts.length !== 3) return null;
  const [username, slug, third] = parts;
  if (KNOWN_ROUTES.has(username.toLowerCase())) return null;
  // /username/slug/play — a direct link into play mode
  const isPlay = parts.length === 3 && third === "play";
  // /username/slug/edit — a direct link into edit mode
  const isEdit = parts.length === 3 && third === "edit";
  if (parts.length === 3 && !isPlay && !isEdit) return null;
  return { username, slug, isPlay: Boolean(isPlay), isEdit: Boolean(isEdit) };
}

/* ---------- guest play: name + save live in localStorage, not the
   database, since a guest has no account row to attach either to ---------- */

const GUEST_NAME_KEY = "ascentery_guest_name";
function loadGuestName() {
  try { return localStorage.getItem(GUEST_NAME_KEY) || ""; } catch { return ""; }
}
function saveGuestName(name) {
  try { localStorage.setItem(GUEST_NAME_KEY, name); } catch {}
}
function guestSaveKey(worldId) { return `ascentery_guest_save_${worldId}`; }
function loadGuestSave(worldId) {
  try {
    const raw = localStorage.getItem(guestSaveKey(worldId));
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
function writeGuestSave(worldId, value) {
  try { localStorage.setItem(guestSaveKey(worldId), JSON.stringify(value)); } catch {}
}
function deleteGuestSave(worldId) {
  try { localStorage.removeItem(guestSaveKey(worldId)); } catch {}
}

/** Centered, monospace, terminal-style — the guest equivalent of picking
    a character. Whatever's typed becomes char.name for the play session
    (that's the only field Play.jsx ever actually reads off char), saved
    to localStorage so it carries over to the next game they click into,
    same as a signed-in player's chosen default character would. */
function GuestNamePrompt({ onDone }) {
  const [name, setName] = useState(() => loadGuestName());
  const inputRef = useRef(null);
  useEffect(() => { inputRef.current?.focus(); }, []);
  // Starts matching the background — invisible, not a visible default —
  // so there's nothing to flash away from once the real admin-chosen
  // color loads a moment later. The input remains fully usable during
  // this brief window even though nothing is visibly drawn yet.
  const [screen, setScreen] = useState({ theme: "current", labelWeight: "bold", glow: "default", color: "#0a0b10" });
  useEffect(() => {
    loadSetting("guest_name_screen").then((v) => setScreen((s) => ({ ...s, ...v }))).catch(() => {});
  }, []);
  const isRetro = screen.theme === "retro";
  const isBold = screen.labelWeight === "bold";
  const isGlow = screen.glow === "glow";
  const color = screen.color || "#4aff6e";

  const submit = () => {
    const trimmed = name.trim().slice(0, 18);
    if (!trimmed) return;
    saveGuestName(trimmed);
    onDone(trimmed);
  };

  return (
    <div onClick={() => inputRef.current?.focus()}
      style={{ height: "100vh", width: "100vw", overflow: "hidden", boxSizing: "border-box",
      display: "grid", placeItems: "center", background: "#0a0b10", padding: 24, position: "relative" }}>
      <style>{`
        @keyframes guest-cursor-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
        @keyframes guest-name-glow {
          0%, 100% { text-shadow: 0 0 4px ${color}, 0 0 10px ${color}88; }
          50% { text-shadow: 0 0 8px ${color}, 0 0 22px ${color}cc, 0 0 34px ${color}66; }
        }
      `}</style>

      {/* TV scanlines — a fixed overlay of thin repeating horizontal
          lines, purely decorative, so it sits above everything else but
          never intercepts clicks/typing. Tied to theme, independent of
          the glow setting below. */}
      {isRetro && (
        <div aria-hidden style={{ position: "absolute", inset: 0, pointerEvents: "none",
          background: "repeating-linear-gradient(to bottom, rgba(0,0,0,0.25) 0px, rgba(0,0,0,0.25) 1px, transparent 1px, transparent 3px)" }} />
      )}

      <div style={{ fontFamily: "Menlo, 'Courier New', monospace", textAlign: "left" }}>
        <div style={{ fontSize: 20, color, marginBottom: 22, fontWeight: isBold ? 700 : 400,
          animation: isGlow ? "guest-name-glow 2.2s ease-in-out infinite" : "none" }}>
          What is your name?
        </div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "flex-start", fontSize: 20 }}>
          <input ref={inputRef} value={name} maxLength={18}
            onChange={(e) => setName(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && submit()}
            style={{ background: "none", border: "none", outline: "none", caretColor: "transparent",
              color, fontFamily: "inherit", fontSize: "inherit", padding: 0,
              animation: isGlow ? "guest-name-glow 2.2s ease-in-out infinite" : "none",
              width: `${Math.max(1, name.length)}ch` }} />
          <span aria-hidden style={{ color, animation: "guest-cursor-blink 1s step-end infinite" }}>
            {"\u2588"}
          </span>
        </div>
      </div>
    </div>
  );
}

export default function Ascentery() {
  /* T and P are mutated in place by applyDefaultTheme, not replaced — every
     component reads T.bone/P.ink as a plain property access at render
     time, so nothing needs to re-import them. This gate just makes sure
     that mutation has already happened before the first real render, on
     every screen including Auth, rather than flashing the built-in colours
     first and jumping to a theme a moment later. */
  const [themeReady, setThemeReady] = useState(false);
  useEffect(() => {
    let cancelled = false;
    applyDefaultTheme(T, P).finally(() => { if (!cancelled) setThemeReady(true); });
    return () => { cancelled = true; };
  }, []);

  // Signing out from a direct /signout or /logout visit needs to happen
  // once, as a real side effect, not folded into the view-selection
  // logic below — it's an action against the current session, not a
  // page. Fires before the very first render if the path calls for it.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const segment = window.location.pathname.replace(/^\/+|\/+$/g, "").split("/")[0].toLowerCase();
    if (SIGNOUT_WORDS.has(segment)) {
      signOut().catch(() => {});
      window.history.replaceState({}, "", "/");
    }
  }, []);

  const [session, setSession] = useState(null);
  const [booting, setBooting] = useState(true);
  const [loadError, setLoadError] = useState(null);
  // Incremented to trigger a silent retry after a transient load failure.
  // One automatic retry covers the common idle case where the token
  // refresh hadn't landed yet; if it still fails the error screen shows.
  const [loadAttempt, setLoadAttempt] = useState(0);
  const [view, setView] = useState(() => {
    if (typeof window !== "undefined" && window.location.pathname.replace(/^\/+|\/+$/g, "") === "purchase-successful") {
      const amount = new URLSearchParams(window.location.search).get("amount");
      return { name: "purchaseSuccessful", amount };
    }
    const pathUsername = usernameFromPath();
    if (pathUsername) return { name: "creatorProfile", username: pathUsername };
    // Restored only as a fallback when the URL itself named nothing more
    // specific — a real /mine or /browse visit still wins outright. This
    // is what actually survives a browser silently discarding and
    // reloading a backgrounded tab (iOS Safari does this under memory
    // pressure in particular): without it, that reload always lands back
    // on whatever the bare "/" path resolves to, which looked from the
    // outside like the app "exiting" whatever page was open.
    let restored = null;
    try {
      const saved = sessionStorage.getItem("ascentery_view");
      if (saved) restored = JSON.parse(saved);
      if (restored?.name === "auth") restored = null;
    } catch {}
    return viewFromPath() ?? restored ?? { name: "home" };
  });

  // Kept in sync on every navigation, not just at the end of a session —
  // a reload can happen at any point, not only after a clean exit.
  useEffect(() => {
    if (view.name === "auth") return;
    try { sessionStorage.setItem("ascentery_view", JSON.stringify(view)); } catch {}
  }, [view]);
  // A /username/gamename visit shows that username's profile immediately
  // (already correct and meaningful on its own) while this resolves in
  // the background, then upgrades the view to the actual game once the
  // lookup succeeds. Left as the profile if it fails — CreatorProfile's
  // own "could not be found" state already covers a username that
  // doesn't exist either, so nothing further needs to be shown here for
  // a bad game slug under a real username.
  const [pendingGameSlug] = useState(() => gameSlugFromPath());
  // Tracks whether pendingGameSlug has already been resolved so the
  // effect below doesn't fire a second time when session gets a new
  // object reference on TOKEN_REFRESHED (window focus → token refresh
  // → setSession(s) → effect re-runs → go("edit"/"game") called again,
  // which can cause EditGame to remount and navigate away from /edit).
  const pendingGameSlugResolved = useRef(false);
  const [games, setGames] = useState([]);
  const [me, setMe] = useState(null);
  const [friends, setFriends] = useState(seedFriends);
  const [chars, setChars] = useState([]);

  const [saves, setSaves] = useState({}); // `${worldId}:${charId}` -> { state, log }

  const go = (name, params = {}) => {
    setView({ name, ...params });
    if (typeof window === "undefined") return;
    // Profile pages are reached two ways: by username (anyone's, or
    // your own once you've claimed one) or by selfId (the "Profile
    // Page" dropdown link specifically, which goes by id rather than
    // username so it still works for someone who hasn't claimed a
    // username yet — see loadCreatorProfileById's own comment in db.js).
    // Only the first of those carries a username in params directly;
    // the second needs it resolved from the viewer's own profile.
    const profileUsername = name === "creatorProfile"
      ? params.username ?? (params.selfId && params.selfId === me?.id ? me?.username : null)
      : null;
    // A game's own URL, /username/slug, needs both pieces from whoever
    // called go() — not every call site passes them yet, so this
    // degrades to the plain root rather than producing a broken,
    // half-built URL when they're missing.
    const gamePath = name === "game" && params.authorUsername && params.slug
      ? `/${params.authorUsername}/${params.slug}`
      : null;
    // Playing a game: use /username/slug/play when both pieces are known.
    // Falls back to "/" if they're missing (same degradation as "game").
    const playPath = name === "play" && params.authorUsername && params.slug
      ? `/${params.authorUsername}/${params.slug}/play`
      : null;
    // Editing a game: use /username/slug/edit when both pieces are known.
    // Falls back to "/" if they're missing (same degradation as "game").
    const editPath = name === "edit" && params.authorUsername && params.slug
      ? `/${params.authorUsername}/${params.slug}/edit`
      : null;
    const path = profileUsername ? `/${profileUsername}` : editPath ?? playPath ?? gamePath ?? CANONICAL_URL[name] ?? "/";
    if (window.location.pathname !== path) window.history.replaceState({}, "", path);
  };
  const refreshWorlds = async () => {
    if (!session) return;
    try { setGames(await loadWorlds(session.user.id)); } catch (e) { console.error(e); }
  };

  // One listener handles first load, sign-in, sign-out and token refresh.
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      setSession(data.session);
      if (!data.session) setBooting(false);
    });
    const { data: sub } = supabase.auth.onAuthStateChange((event, s) => {
      // During 2FA step 1, signInWithPassword + signOut fires this handler
      // twice. The Auth component sets suppressAuthChange.current = true
      // for that window so we ignore those transient state changes and
      // don't accidentally route the user away mid-flow.
      if (suppressAuthChange.current) return;
      setSession(s);
      if (!s) { setMe(null); setChars([]); setSaves({}); setBooting(false); }
      if (event === "PASSWORD_RECOVERY") setView({ name: "resetPassword" });
      if (event === "SIGNED_IN") {
        // Use go() so the URL also updates away from /signin, not just the view.
        setView((v) => {
          if (v.name === "auth") {
            if (typeof window !== "undefined") window.history.replaceState({}, "", "/");
            return { name: "home" };
          }
          return v;
        });
      }
    });
    return () => sub.subscription.unsubscribe();
  }, []);

  // Resolves a pending /username/gamename visit once a session exists —
  // profiles RLS requires authentication just to read it at all, so
  // there's no point attempting this any earlier. go() (not setView
  // directly) so the address bar also settles onto this game's own
  // canonical URL once it's known, same as any other navigation.
  useEffect(() => {
    if (!session || !pendingGameSlug) return;
    // Only resolve once — token refreshes on window-refocus fire
    // onAuthStateChange(TOKEN_REFRESHED) → setSession(newRef) → this
    // effect re-runs even though neither session identity nor
    // pendingGameSlug changed. A second call to go("edit"/…) can cause
    // EditGame to remount and navigate away from /edit back to the game
    // detail page, which is the regression this guard prevents.
    if (pendingGameSlugResolved.current) return;
    pendingGameSlugResolved.current = true;
    let cancelled = false;
    loadGameBySlug(pendingGameSlug.username, pendingGameSlug.slug)
      .then((worldId) => {
        if (!cancelled) {
          if (pendingGameSlug.isEdit) {
            // /username/slug/edit — restore the edit view directly.
            go("edit", {
              id: worldId,
              authorUsername: pendingGameSlug.username,
              slug: pendingGameSlug.slug,
            });
          } else {
            // /username/slug/play lands on the game detail page — the user
            // still needs to pick a character before play can start, so we
            // can't jump straight into play mode from a cold load. Land on
            // the game detail view (same as /username/slug) and let them
            // click Start from there, which will then set the /play URL.
            go("game", {
              id: worldId,
              from: "browse",
              authorUsername: pendingGameSlug.username,
              slug: pendingGameSlug.slug,
            });
          }
        }
      })
      .catch(() => { /* left showing the profile view set above */ });
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [session, pendingGameSlug]);

  /* purchase-successful is detected synchronously in the view initializer
     above, amount and all — this just handles refreshing the balance,
     since that's set by the webhook, not by this redirect, and there can
     be a second or two of lag before it's actually reflected. */
  useEffect(() => {
    if (view.name !== "purchaseSuccessful" || !session) return;
    const t = setTimeout(() => {
      loadMe(session.user.id).then(setMe).catch(() => {});
    }, 1500);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view.name, session]);

  // Guests never get a session, so the effect below (which loads
  // everything scoped to a real signed-in user) never runs for them —
  // this is the separate, guest-safe path that still lets them see
  // published games on Browse. loadWorlds's own OR clause already
  // returns every published game regardless of owner, so a placeholder
  // id (same convention its own profiles fallback already uses) is all
  // that's needed here, not a real account.
  const [guestGames, setGuestGames] = useState([]);
  const [guestGamesLoaded, setGuestGamesLoaded] = useState(false);
  const [guestPlayEnabled, setGuestPlayEnabled] = useState(null); // null = not yet known
  useEffect(() => {
    loadSetting("guest_play_enabled").then((v) => setGuestPlayEnabled(v?.enabled === true)).catch(() => setGuestPlayEnabled(false));
  }, []);
  useEffect(() => {
    if (session) return;
    let cancelled = false;
    loadWorlds("00000000-0000-0000-0000-000000000000")
      .then((ws) => { if (!cancelled) { setGuestGames(ws); setGuestGamesLoaded(true); } })
      .catch((e) => { if (!cancelled) { console.error("guest games failed to load:", e); setGuestGamesLoaded(true); } });
    return () => { cancelled = true; };
  }, [session]);

  // Pull everything that belongs to this user once we have a session.
  // loadAttempt is incremented to trigger a single silent retry when the
  // first attempt fails — covers the common case where the tab was idle
  // long enough that the token refresh hadn't completed before the query
  // ran. The retry waits 2 s to give the refresh time to settle; if it
  // still fails the error screen is shown.
  useEffect(() => {
    if (!session) return;
    let cancelled = false;
    (async () => {
      try {
        const uid = session.user.id;
        const [m, cs, sv, ws] = await Promise.all([
          loadMe(uid), loadCharacters(uid), loadSaves(uid), loadWorlds(uid),
        ]);
        if (cancelled) return;
        setMe(m); setChars(cs); setSaves(sv); setGames(ws); setLoadError(null);
      } catch (err) {
        if (cancelled) return;
        if (loadAttempt === 0) {
          // First failure — wait briefly for any in-flight token refresh,
          // then retry once before showing the error screen.
          setTimeout(() => { if (!cancelled) setLoadAttempt(1); }, 2000);
        } else {
          setLoadError(err.message);
        }
      } finally {
        if (!cancelled) setBooting(false);
      }
    })();
    return () => { cancelled = true; };
  }, [session, loadAttempt]);

  if (!themeReady) return null;
  if (booting) return <Shell><Splash1 /></Shell>;
  if (!session) {
    if (guestPlayEnabled === null) return <Shell><Splash1 /></Shell>; // wait to know which flow applies
    if (!guestPlayEnabled) return <Shell><Auth /></Shell>; // original behavior, unchanged
    if (view.name === "auth") return <Shell><Auth /></Shell>;

    if (view.name === "guestName") {
      return (
        <GuestNamePrompt onDone={(name) => go(view.returnTo?.name ?? "game", view.returnTo ?? {})} />
      );
    }

    if (view.name === "play") {
      const guestName = loadGuestName();
      if (!guestName) {
        // Shouldn't normally happen — GameDetail routes to guestName
        // first when there's no name yet — but this is the safe fallback
        // if "play" is ever reached directly without one.
        go("guestName", { returnTo: { name: "play", id: view.id } });
        return <Shell><Splash1 /></Shell>;
      }
      return (
        <PlayLoader
          worldId={view.id}
          char={{ name: guestName }}
          save={loadGuestSave(view.id)}
          onSave={(v) => writeGuestSave(view.id, v)}
          onExit={() => go("game", { id: view.id })}
          onHome={() => go("browse")}
        />
      );
    }

    return (
      <Shell>
        <TopBar me={null} view={view} go={go} />
        <main style={{ maxWidth: 1080, margin: "0 auto", padding: "26px 22px 80px" }}>
          {view.name === "creatorProfile"
            ? <CreatorProfile username={view.username} selfId={view.selfId} me={null} go={go} />
            : (view.name === "support" || view.name === "support_our_project")
              ? <SupportPage go={go} />
              : !guestGamesLoaded ? <Splash1 /> :
                view.name === "game"
                  ? <GameDetail game={guestGames.find((g) => g.id === view.id)} chars={[]} saves={{}} setSaves={() => {}}
                      userId={null} defaultCharacterId={null} go={go} from={view.from ?? "browse"} isMine={false}
                      guestName={loadGuestName()} isGuest
                      guestSave={loadGuestSave(view.id)} onClearGuestSave={() => deleteGuestSave(view.id)} />
                  : view.name === "home"
                    ? <Landing games={guestGames.filter((g) => g.published)} go={go} />
                    : <Browse games={guestGames.filter((g) => g.published)} go={go} />}
        </main>
      </Shell>
    );
  }

  // Rendered before the "me" guard below on purpose — a fresh recovery
  // session is real and authenticated, but loadMe() may not have
  // resolved yet, and this screen doesn't need the profile anyway.
  if (view.name === "resetPassword") return <Shell><ResetPasswordPage go={go} /></Shell>;
  if (loadError) return (
    <Shell>
      <div style={{ minHeight: "100vh", display: "grid", placeItems: "center", padding: 24 }}>
        <div style={{ maxWidth: 420 }}>
          <div style={{ fontFamily: T.serif, fontSize: 22, marginBottom: 8 }}>Couldn't load your account</div>
          <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7 }}>{loadError}</p>
          <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
            <Btn kind="solid" onClick={() => window.location.reload()}>Refresh</Btn>
            <Btn onClick={() => signOut()}>Sign out</Btn>
          </div>
        </div>
      </div>
    </Shell>
  );
  if (!me) return <Shell><Splash1 /></Shell>;

  if (view.name === "purchaseSuccessful") {
    const hasUsername = Boolean(me.username);
    return (
      <Shell>
        <div style={{ minHeight: "100vh", display: "grid", placeItems: "center", padding: 24 }}>
          <div style={{ maxWidth: 440, textAlign: "center" }}>
            <div style={{ fontFamily: T.serif, fontSize: 26, marginBottom: 12, color: T.bone }}>
              Congratulations!
            </div>
            <p style={{ fontFamily: T.serif, fontSize: 16, lineHeight: 1.6, color: T.boneDim, margin: "0 0 26px" }}>
              {view.amount
                ? `You've topped up with $${view.amount}. `
                : "Your top-up went through. "}
              {hasUsername ? "Time to build something." : "One more thing before you can publish a world."}
            </p>
            <Btn kind="solid" onClick={() => {
              go(hasUsername ? "mine" : "username", hasUsername ? {} : { next: "mine" });
            }}>
              {hasUsername ? "Start creating" : "Choose a username"}
            </Btn>
          </div>
        </div>
      </Shell>
    );
  }

  if (view.name === "play") {
    const key = `${view.id}:${view.charId}`;
    return (
      <PlayLoader
        worldId={view.id}
        char={chars.find((c) => c.id === view.charId)}
        save={saves[key]}
        onSave={(v) => {
          setSaves((s) => ({ ...s, [key]: v }));
          writeSave({ userId: me.id, worldId: view.id, characterId: view.charId, ...v })
            .then(() => checkBadge(view.id))
            .catch((e) => console.error("save failed", e));
        }}
        onExit={() => go("game", { id: view.id })}
        onHome={() => go("mine")}
        me={me}
      />
    );
  }

  return (
    <Shell>
      <TopBar me={me} view={view} go={go} />
      <main style={{ maxWidth: 1080, margin: "0 auto", padding: "26px 22px 80px" }}>
        {view.name === "home" && <Home games={games} saves={saves} go={go} />}
        {view.name === "browse" && <Browse games={games.filter((g) => g.published)} go={go} />}
        {view.name === "mine" && <Mine games={games.filter((g) => g.authorId === me.id)} me={me} go={go} />}
        {view.name === "friends" && <Friends friends={friends} setFriends={setFriends} games={games} go={go} />}
        {view.name === "profile" && <Profile me={me} setMe={setMe} chars={chars} setChars={setChars} go={go} />}
        {view.name === "creator" && <CreatorPage me={me} go={go} />}
        {view.name === "admin" && <AdminPage me={me} go={go} />}
        {view.name === "username" && <UsernamePage me={me} setMe={setMe} go={go} reason={view.reason} next={view.next} />}
        {view.name === "create" && <Create key={view.resumeId ?? "new"} me={me} refreshWorlds={refreshWorlds} go={go} resumeId={view.resumeId} />}
        {view.name === "game" && <GameDetail game={games.find((g) => g.id === view.id)} chars={chars} saves={saves} setSaves={setSaves} userId={me.id} defaultCharacterId={me.defaultCharacterId} go={go} from={view.from ?? "browse"} isMine={games.find((g) => g.id === view.id)?.authorId === me.id} isAdmin={Boolean(me.isAdmin)} onRankChange={refreshWorlds} />}

        {view.name === "creatorProfile" && <CreatorProfile username={view.username} selfId={view.selfId} me={me} go={go} />}

        {view.name === "avatar" && <AvatarPage me={me} setMe={setMe} go={go} />}

        {view.name === "settings" && <SettingsPage me={me} go={go} />}
        {(view.name === "support" || view.name === "support_our_project") && <SupportPage go={go} />}
        {view.name === "edit" && (() => {
          const editGame = games.find((g) => g.id === view.id);
          // Only the owner (or an admin) may access the edit page.
          // Published games appear in everyone's `games` list, so a plain
          // find() is not enough — the ownership check must be explicit.
          if (editGame && editGame.authorId !== me.id && !me.isAdmin) {
            return <Empty title="Not your world." line="You can only edit worlds you created." />;
          }
          return <EditGame game={editGame} refreshWorlds={refreshWorlds} me={me} setMe={setMe} go={go} chars={chars} initialTab={view.tab} />;
        })()}
      </main>
    </Shell>
  );
}
