// src/lib/marketing.js
// Data layer for trailers, the waitlist, and marketing asset uploads.

import { supabase } from "./supabase";

// ─── internal ────────────────────────────────────────────────────────────────

const row2trailer = (r) => r && ({
  id:            r.id,
  label:         r.label,
  sourceUrl:     r.source_url,
  posterUrl:     r.poster_url,
  durationLabel: r.duration_label,
  isActive:      r.is_active,
  sortOrder:     r.sort_order,
  createdAt:     r.created_at,
});

// ─── trailers ─────────────────────────────────────────────────────────────────

/** The one trailer the public hero shows. Returns null when nothing is
    configured — every caller treats "no trailer" as a normal state. */
export async function loadActiveTrailer() {
  const { data, error } = await supabase
    .from("trailers")
    .select("*")
    .eq("is_active", true)
    .order("sort_order", { ascending: true })
    .limit(1)
    .maybeSingle();
  if (error) return null;
  return row2trailer(data);
}

/** Admin list of all trailers. */
export async function loadTrailers() {
  const { data, error } = await supabase
    .from("trailers")
    .select("*")
    .order("sort_order", { ascending: true })
    .order("created_at", { ascending: false });
  if (error) throw error;
  return (data ?? []).map(row2trailer);
}

/** Create or update a trailer row. Pass id to update, omit to insert. */
export async function saveTrailer(t) {
  const payload = {
    label:          t.label         ?? "",
    source_url:     t.sourceUrl     ?? null,
    poster_url:     t.posterUrl     ?? null,
    duration_label: t.durationLabel ?? null,
    sort_order:     t.sortOrder     ?? 0,
  };
  const q = t.id
    ? supabase.from("trailers").update(payload).eq("id", t.id).select().single()
    : supabase.from("trailers").insert(payload).select().single();
  const { data, error } = await q;
  if (error) throw error;
  return row2trailer(data);
}

export async function deleteTrailer(id) {
  const { error } = await supabase.from("trailers").delete().eq("id", id);
  if (error) throw error;
}

/** Make one trailer active. Done in two statements because PostgREST has
    no transactions; the brief window where none is active is harmless. */
export async function setActiveTrailer(id) {
  const a = await supabase.from("trailers").update({ is_active: false }).neq("id", id);
  if (a.error) throw a.error;
  const b = await supabase.from("trailers").update({ is_active: true }).eq("id", id);
  if (b.error) throw b.error;
}

// ─── waitlist ─────────────────────────────────────────────────────────────────

/** Join the waitlist. Silently succeeds if the address is already on it —
    same reasoning as the password-reset copy: otherwise the form becomes a
    way to check who has signed up.
    Uses plain insert (not upsert) to avoid triggering Supabase's UPDATE RLS
    check, which blocks anon even when ignoreDuplicates means no row is
    actually updated. Duplicate emails are caught by the unique constraint
    (code "23505") and silently ignored. */
export async function joinWaitlist({ email, note, source = "landing" }) {
  const clean = String(email ?? "").trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clean))
    throw new Error("That does not look like an email address.");
  const { error } = await supabase
    .from("waitlist")
    .insert({ email: clean, note: (note ?? "").slice(0, 500) || null, source });
  if (error && error.code !== "23505") throw error;
  return true;
}

// ─── asset uploads ────────────────────────────────────────────────────────────

/** Upload a poster image to B2 via the upload-marketing-poster edge function.
    Optionally pass a trailerId to have the trailers row updated automatically.
    @param {File}   file       — image file from <input type="file">
    @param {string} [trailerId] — UUID of the trailer row to attach it to
    @returns {Promise<string>} public CDN URL
*/
export async function uploadMarketingPoster(file, trailerId = "") {
  const { data: { session } } = await supabase.auth.getSession()
  if (!session) throw new Error("Not signed in.")

  const res = await fetch(
    `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/upload-marketing-poster`,
    {
      method: "POST",
      headers: {
        "Content-Type": file.type || "image/jpeg",
        Authorization: `Bearer ${session.access_token}`,
        "x-trailer-id": trailerId,
        "x-filename": file.name || "poster.jpg",
      },
      body: file,
    }
  )

  const body = await res.json().catch(() => ({}))
  if (!res.ok) throw new Error(body.error || `Upload failed (${res.status})`)
  if (body.warning) console.warn("upload-marketing-poster:", body.warning)
  return body.posterUrl
}

/** Check whether a single email has been invited — callable by anon users
    on the sign-up page so they can skip the invite-code field if they're
    on the allowlist. Uses the is_email_invited() SECURITY DEFINER RPC so
    no other waitlist rows are exposed. */
export async function isEmailInvited(email) {
  const clean = String(email ?? "").trim().toLowerCase();
  if (!clean) return false;
  const { data, error } = await supabase.rpc("is_email_invited", { check_email: clean });
  if (error) return false;
  return Boolean(data);
}

/** Admin: stamp invited_at on a waitlist row. */
export async function markWaitlistInvited(id) {
  const { error } = await supabase
    .from("waitlist")
    .update({ invited_at: new Date().toISOString() })
    .eq("id", id);
  if (error) throw error;
}

/** Admin: load all waitlist entries, newest first. */
export async function loadWaitlist() {
  const { data, error } = await supabase
    .from("waitlist")
    .select("id, email, note, source, invited_at, created_at")
    .order("created_at", { ascending: false });
  if (error) throw error;
  return data ?? [];
}

/** Upload a trailer video to B2 via the upload-marketing-video edge function.
    Sends the raw file bytes as the request body with metadata in headers —
    no base64, no FormData parsing, works for files of any size.

    @param {File}   file       — video file from <input type="file">
    @param {string} trailerId  — UUID of the trailer row to attach it to
    @returns {Promise<string>} public CDN URL
*/
export async function uploadMarketingVideo(file, trailerId) {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) throw new Error("Not signed in.");

  const res = await fetch(
    `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/upload-marketing-video`,
    {
      method: "POST",
      headers: {
        "Content-Type": file.type || "video/mp4",
        Authorization: `Bearer ${session.access_token}`,
        "x-trailer-id": trailerId,
        "x-filename": file.name || "video.mp4",
      },
      body: file,
    }
  );

  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(body.error || `Upload failed (${res.status})`);
  if (body.warning) console.warn("upload-marketing-video:", body.warning);
  return body.videoUrl;
}
