import React, { useState } from "react";
import {
  SORTS,
  sortWorlds,
} from "../lib/db";
import { useNarrow } from "../hooks";
import { roomBanner, fallbackSceneTag } from "../lib/svgScene";
import { T, grid, inputStyle } from "../theme";
import { Chip, Empty, Splash } from "../ui/primitives";

// Same idea as ArtTab's room placeholder, extended to a game's own cover
// — the "Your games" / Browse / Home cards never got this fix, since
// they render through GameCard, a completely different component from
// the one that was actually touched. Infers from the game's own title
// and blurb rather than a room's name/desc, since a cover represents
// the whole world, not one specific room.
const SCENE_TAG_WORDS = [
  "tavern", "temple", "guild", "forest", "desert", "sea", "snow", "mountain", "ruins",
  "market", "fountain", "street", "gate", "dark",
];
function gameSceneFallbackSvg(g) {
  const text = `${g?.title ?? ""} ${g?.blurb ?? ""}`.toLowerCase();
  const matched = SCENE_TAG_WORDS.filter((w) => text.includes(w));
  const tags = matched.length ? matched : [fallbackSceneTag(g?.id ?? "x")];
  return roomBanner(tags, g?.id ?? "x", 400, 225);
}

export function Browse({ games, go }) {
  const [q, setQ] = useState("");
  const [sort, setSort] = useState("staff");
  const narrow = useNarrow();

  const ranked = sortWorlds(games, sort);
  const shown = ranked.filter((g) => (g.title + g.author + g.blurb).toLowerCase().includes(q.toLowerCase()));

  // The showcase is the top staff pick (the most played world until an admin
  // has ranked anything), whatever the list below is sorted by. On a phone it costs a whole screen before anyone sees a
  // second title, so it is left out entirely.
  const featured = narrow ? null : sortWorlds(games, "staff")[0];
  const featuredLabel = featured && (featured.staffRank ?? 100) < 100 ? "staff pick" : "most played";
  const rest = featured ? shown.filter((g) => g.id !== featured.id) : shown;

  return (
    <div className="pf-in">
      {featured && (
        <div className="pf-card" onClick={() => go("game", { id: featured.id, authorUsername: featured.authorUsername, slug: featured.slug, from: "browse" })}
          style={{ display: "grid", gridTemplateColumns: "minmax(0,1.4fr) minmax(0,1fr)",
            gap: 24, marginBottom: 34, alignItems: "center" }}>
          <Splash seed={featured.id} src={featured.coverUrl}
            fallbackSvg={!featured.coverUrl ? gameSceneFallbackSvg(featured) : undefined} ratio={0.5625} />
          <div>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.ochre, marginBottom: 8 }}>{featuredLabel}</div>
            <div className="pf-title" style={{ fontFamily: T.serif, fontSize: 30, lineHeight: 1.15, marginBottom: 8 }}>
              {featured.title}
            </div>
            <p style={{ fontFamily: T.serif, fontSize: 16, lineHeight: 1.55, color: T.boneDim, margin: "0 0 12px" }}>
              {featured.blurb}
            </p>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
              {featured.author} &middot; {featured.rooms} rooms &middot; {featured.plays.toLocaleString()} plays
            </div>
          </div>
        </div>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18, flexWrap: "wrap" }}>
        <select
          value={sort}
          onChange={(e) => setSort(e.target.value)}
          aria-label="Sort worlds"
          style={{ background: T.ground, color: T.bone, border: `1px solid ${T.edge}`, borderRadius: 2,
            fontFamily: T.serif, fontSize: 17, padding: "6px 8px", cursor: "pointer" }}>
          {SORTS.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
        </select>

        <span style={{ flex: 1 }} />

        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="search worlds"
          style={{ ...inputStyle, width: narrow ? "100%" : 200, fontFamily: T.mono, fontSize: 12, padding: "7px 10px" }} />
      </div>

      <div style={grid}>
        {rest.map((g) => (
          <GameCard key={g.id} g={g} go={go} onClick={() => go("game", { id: g.id, authorUsername: g.authorUsername, slug: g.slug, from: "browse" })}
            meta={sort === "week" && g.weekPlays ? `${g.weekPlays.toLocaleString()} plays this week` : null} />
        ))}
      </div>
      {!shown.length && <Empty title="Nothing matches that." line="Try a shorter word, or clear the search." />}

      {/* Quiet by design — below everything else, not competing with
          browsing. PLACEHOLDER URLS: replace with your real Ko-fi /
          Buy Me a Coffee / Patreon links before this goes live. */}
      <div style={{ marginTop: 56, paddingTop: 20, borderTop: "1px solid " + T.edge,
        display: "flex", justifyContent: "center", gap: 18, flexWrap: "wrap" }}>
        <a href="https://ko-fi.com/YOUR_USERNAME" target="_blank" rel="noopener noreferrer"
          style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, textDecoration: "none" }}>
          Support on Ko-fi
        </a>
        <a href="https://www.buymeacoffee.com/YOUR_USERNAME" target="_blank" rel="noopener noreferrer"
          style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, textDecoration: "none" }}>
          Buy me a coffee
        </a>
        <a href="https://www.patreon.com/YOUR_USERNAME" target="_blank" rel="noopener noreferrer"
          style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, textDecoration: "none" }}>
          Patreon
        </a>
      </div>
    </div>
  );
}

export function GameCard({ g, onClick, showStatus, meta, go }) {
  return (
    <div className="pf-card pf-in" onClick={onClick}>
      <Splash seed={g.id} pending={g.status === "generating"} src={g.coverUrl}
        fallbackSvg={!g.coverUrl ? gameSceneFallbackSvg(g) : undefined} />
      <div style={{ padding: "10px 2px 0" }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
          <div className="pf-title" style={{ fontFamily: T.serif, fontSize: 18, flex: 1, lineHeight: 1.25 }}>{g.title}</div>
          {showStatus && <Chip status={g.status} published={g.published} />}
        </div>
        <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginTop: 5 }}>
          {go && g.author?.startsWith("@") ? (
            <button className="pf-btn"
              onClick={(e) => { e.stopPropagation(); go("creatorProfile", { username: g.author.slice(1) }); }}
              style={{ background: "none", border: "none", padding: 0, font: "inherit", color: "inherit", cursor: "pointer" }}>
              {g.author}
            </button>
          ) : g.author}
          {" "}· {meta ?? `${g.plays.toLocaleString()} plays`}
        </div>
      </div>
    </div>
  );
}
